{
  "name": "SpinStacks",
  "description": "A sophisticated, data-driven platform for slot game exploration, providing RTP analysis, volatility metrics, and demo play without the casino hype.",
  "requestFramePermissions": []
}

import React from 'react';
import ReactDOM from 'react-dom/client';
import App from './App';

const rootElement = document.getElementById('root');
if (!rootElement) {
  throw new Error("Could not find root element to mount to");
}

const root = ReactDOM.createRoot(rootElement);
root.render(
  <React.StrictMode>
    <App />
  </React.StrictMode>
);

export enum Volatility {
  LOW = 'Low',
  MEDIUM = 'Medium',
  HIGH = 'High',
  EXTREME = 'Extreme'
}

export interface SlotGame {
  id: string;
  title: string;
  provider: string;
  rtp: number;
  volatility: Volatility;
  maxWin: string;
  reels: string;
  paylines: string;
  releaseDate: string;
  thumbnail: string;
  description: string;
  availableAt: string[];
}

export interface GameInsight {
  summary: string;
  pros: string[];
  cons: string[];
  strategyScore: number;
}

import { GoogleGenAI, Type } from "@google/genai";
import { SlotGame, GameInsight } from "../types";

const ai = new GoogleGenAI({ apiKey: process.env.API_KEY || '' });

export const getGameInsights = async (game: SlotGame): Promise<GameInsight> => {
  try {
    const response = await ai.models.generateContent({
      model: "gemini-3-flash-preview",
      contents: `Provide a technical and objective analysis for the slot game "${game.title}" by "${game.provider}". 
      Stats: RTP ${game.rtp}%, Volatility ${game.volatility}, Max Win ${game.maxWin}.
      Focus on mathematical behavior, target player profile, and mechanics. No gambling hype.`,
      config: {
        responseMimeType: "application/json",
        responseSchema: {
          type: Type.OBJECT,
          properties: {
            summary: { type: Type.STRING, description: "A 2-sentence technical summary of the game's profile." },
            pros: { type: Type.ARRAY, items: { type: Type.STRING }, description: "3 technical advantages." },
            cons: { type: Type.ARRAY, items: { type: Type.STRING }, description: "3 technical disadvantages or risks." },
            strategyScore: { type: Type.NUMBER, description: "A score from 1-100 on how much skill/strategy affects RTP through bet sizing or feature choices." }
          },
          required: ["summary", "pros", "cons", "strategyScore"]
        }
      }
    });

    return JSON.parse(response.text.trim());
  } catch (error) {
    console.error("Gemini API Error:", error);
    return {
      summary: "Detailed technical data for this game is currently being synthesized. Please check back shortly for full math model breakdown.",
      pros: ["Consistent mechanic execution", "Industry standard RTP", "Robust provider reputation"],
      cons: ["High variance potential", "Session volatility risks", "Limited feature accessibility"],
      strategyScore: 50
    };
  }
};

import React from 'react';
import { SlotGame, Volatility } from '../types';

interface GameCardProps {
  game: SlotGame;
  onClick: (game: SlotGame) => void;
}

const GameCard: React.FC<GameCardProps> = ({ game, onClick }) => {
  const getVolatilityColor = (v: Volatility) => {
    switch (v) {
      case Volatility.LOW: return 'bg-emerald-100 text-emerald-700';
      case Volatility.MEDIUM: return 'bg-blue-100 text-blue-700';
      case Volatility.HIGH: return 'bg-amber-100 text-amber-700';
      case Volatility.EXTREME: return 'bg-rose-100 text-rose-700';
      default: return 'bg-gray-100 text-gray-700';
    }
  };

  return (
    <div 
      className="bg-white rounded-xl border border-gray-200 overflow-hidden hover:shadow-lg transition-all cursor-pointer group flex flex-col h-full"
      onClick={() => onClick(game)}
    >
      <div className="relative aspect-[16/10] overflow-hidden">
        <img 
          src={game.thumbnail} 
          alt={game.title} 
          className="w-full h-full object-cover group-hover:scale-105 transition-transform duration-500"
        />
        <div className="absolute top-3 left-3 flex gap-2">
           <span className="px-2 py-1 bg-white/90 backdrop-blur text-[10px] font-bold uppercase tracking-wider rounded border border-gray-200 shadow-sm">
            {game.provider}
          </span>
        </div>
      </div>

      <div className="p-4 flex flex-col flex-grow">
        <h3 className="text-lg font-bold text-gray-900 mb-1 leading-tight">{game.title}</h3>

        <div className="flex items-center gap-2 mb-4">
          <span className={`px-2 py-0.5 rounded text-[10px] font-bold uppercase tracking-wider ${getVolatilityColor(game.volatility)}`}>
            {game.volatility} Volatility
          </span>
          <span className="text-xs text-gray-400">•</span>
          <span className="text-xs font-semibold text-gray-600">{game.rtp}% RTP</span>
        </div>

        <div className="mt-auto grid grid-cols-2 gap-2 border-t border-gray-100 pt-4">
          <div className="text-[10px] text-gray-500">
            <p className="uppercase font-semibold text-[9px] mb-0.5">Max Win</p>
            <p className="text-gray-900 font-bold">{game.maxWin}</p>
          </div>
          <div className="text-[10px] text-gray-500 text-right">
            <p className="uppercase font-semibold text-[9px] mb-0.5">Format</p>
            <p className="text-gray-900 font-bold">{game.reels}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GameCard;

import React, { useState, useEffect } from 'react';
