  useEffect(() => {
    const fetchInsights = async () => {
      setLoading(true);
      const data = await getGameInsights(game);
      setInsights(data);
      setLoading(false);
    };
    fetchInsights();
  }, [game]);

  // Comparison data
  const chartData = [
    { name: 'This Game', rtp: game.rtp, fill: '#4F46E5' },
    { name: 'Avg Slot', rtp: 96.0, fill: '#D1D5DB' },
