import React, { useState, useMemo } from 'react';
import Navbar from './components/Navbar';
import GameCard from './components/GameCard';
import GameDetailModal from './components/GameDetailModal';
import { MOCK_GAMES } from './constants';
import { SlotGame } from './types';

function App() {
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedGame, setSelectedGame] = useState<SlotGame | null>(null);
  const [filterProvider, setFilterProvider] = useState('All');

  const providers = useMemo(() => {
    const p = new Set(MOCK_GAMES.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, []);

  const filteredGames = useMemo(() => {
    return MOCK_GAMES.filter(game => {
      const matchesSearch = game.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            game.provider.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;
      return matchesSearch && matchesProvider;
    });
  }, [searchQuery, filterProvider]);

  return (
    <div className="min-h-screen pb-20">
      <Navbar />

      {/* Hero Section */}
      <header className="bg-white border-b border-gray-100 py-12 sm:py-20 overflow-hidden relative">
        <div className="absolute top-0 right-0 -mr-20 mt-10 opacity-5 pointer-events-none">
          <svg width="400" height="400" viewBox="0 0 100 100" className="rotate-12">
            <rect x="20" y="20" width="60" height="60" fill="currentColor" className="text-indigo-600" rx="10" />
          </svg>
        </div>

        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
          <div className="max-w-3xl">
            <h1 className="text-4xl sm:text-5xl lg:text-6xl font-extrabold text-gray-900 tracking-tight leading-tight mb-6">
              The Intelligent Way to <span className="text-indigo-600">Explore Slots.</span>
            </h1>
            <p className="text-lg sm:text-xl text-gray-500 mb-10 leading-relaxed">
              Transparent math models, real-time RTP tracking, and objective performance analysis. No hype. Just data.
            </p>

            <div className="relative max-w-xl group">
              <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none">
                <svg className="h-5 h-5 text-gray-400 group-focus-within:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                </svg>
              </div>
              <input
                type="text"
                placeholder="Search games, providers, or mechanics..."
                value={searchQuery}
                onChange={(e) => setSearchQuery(e.target.value)}
                className="block w-full pl-11 pr-4 py-4 border border-gray-200 rounded-2xl bg-white shadow-sm focus:ring-2 focus:ring-indigo-500 focus:border-transparent outline-none transition-all text-gray-900 placeholder-gray-400"
              />
            </div>
          </div>
        </div>
      </header>

      {/* Main Grid */}
      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-12">
        <div className="flex flex-col sm:flex-row sm:items-center justify-between gap-4 mb-8">
          <div>
            <h2 className="text-xl font-bold text-gray-900">Featured Catalog</h2>
            <p className="text-sm text-gray-500">Currently analyzing {filteredGames.length} datasets</p>
          </div>

          <div className="flex items-center gap-2 overflow-x-auto pb-2 sm:pb-0">
            {providers.map(p => (
              <button
                key={p}
                onClick={() => setFilterProvider(p)}
                className={`whitespace-nowrap px-4 py-1.5 rounded-full text-xs font-bold transition-all border ${
                  filterProvider === p 
                  ? 'bg-gray-900 text-white border-gray-900 shadow-md' 
                  : 'bg-white text-gray-600 border-gray-200 hover:border-gray-300'
                }`}
              >
                {p}
              </button>
            ))}
          </div>
        </div>

        {filteredGames.length > 0 ? (
          <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-6 sm:gap-8">
            {filteredGames.map(game => (
              <GameCard 
                key={game.id} 
                game={game} 
                onClick={setSelectedGame} 
              />
            ))}
          </div>
        ) : (
          <div className="text-center py-20 bg-gray-50 rounded-3xl border border-dashed border-gray-300">
             <div className="inline-flex items-center justify-center w-16 h-16 bg-gray-100 rounded-full mb-4">
                <svg className="w-8 h-8 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9.172 9.172a4 4 0 015.656 0M9 10h.01M15 10h.01M21 12a9 9 0 11-18 0 9 9 0 0118 0z" />
                </svg>
             </div>
             <p className="text-gray-500 font-medium">No games found matching your criteria.</p>
             <button 
               onClick={() => { setSearchQuery(''); setFilterProvider('All'); }}
               className="mt-4 text-indigo-600 font-bold hover:underline"
             >
               Clear Filters
             </button>
          </div>
        )}
      </main>

      {/* Footer Disclaimer */}
      <footer className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 mt-24 border-t border-gray-100 pt-12 text-center sm:text-left">
