            <div className="flex items-center gap-2 mb-4">
              <div className="w-6 h-6 bg-indigo-600 rounded flex items-center justify-center">
                <span className="text-white font-bold text-[10px]">S</span>
              </div>
              <span className="text-lg font-bold tracking-tight text-gray-900">SpinStacks</span>
            </div>
            <p className="text-sm text-gray-400 leading-relaxed max-w-sm">
              SpinStacks is an informational tool only. We do not offer real-money gambling. Always play responsibly and check local regulations.
            </p>
          </div>
          <div>
            <h4 className="text-xs font-bold text-gray-900 uppercase tracking-widest mb-4">Resources</h4>
            <ul className="space-y-2 text-sm text-gray-500">
              <li><a href="#" className="hover:text-indigo-600">RTP Explained</a></li>
              <li><a href="#" className="hover:text-indigo-600">Volatility Guide</a></li>
              <li><a href="#" className="hover:text-indigo-600">Provider List</a></li>
            </ul>
          </div>
          <div>
            <h4 className="text-xs font-bold text-gray-900 uppercase tracking-widest mb-4">Legal</h4>
            <ul className="space-y-2 text-sm text-gray-500">
              <li><a href="#" className="hover:text-indigo-600">Privacy Policy</a></li>
              <li><a href="#" className="hover:text-indigo-600">Terms of Use</a></li>
              <li><a href="#" className="hover:text-indigo-600">Cookies</a></li>
            </ul>
          </div>
        </div>
        <div className="py-8 border-t border-gray-50 flex flex-col sm:flex-row justify-between items-center gap-4">
          <p className="text-xs text-gray-400">© 2024 SpinStacks Analytics. Built for transparency.</p>
          <div className="flex items-center gap-4 grayscale opacity-40">
            <span className="text-[10px] font-bold border border-gray-300 px-2 py-0.5 rounded">18+</span>
            <span className="text-[10px] font-bold border border-gray-300 px-2 py-0.5 rounded">eCOGRA</span>
            <span className="text-[10px] font-bold border border-gray-300 px-2 py-0.5 rounded">RNG CERT</span>
          </div>
        </div>
      </footer>

      {/* Modals */}
      {selectedGame && (
        <GameDetailModal 
          game={selectedGame} 
          onClose={() => setSelectedGame(null)} 
        />
      )}
    </div>
  );
}

export default App;

