      case Volatility.HIGH: return 'bg-amber-50 text-amber-700 border-amber-100';
      case Volatility.EXTREME: return 'bg-rose-50 text-rose-700 border-rose-100';
      default: return 'bg-gray-50 text-gray-700 border-gray-100';
    }
  };

  return (
    <div 
