export default AdminDashboard;

import React, { useState, useMemo, useEffect } from 'react';
import { SlotGame, Volatility } from '../types';
import GameDetailModal from './GameDetailModal';

interface AdminDashboardProps {
  games: SlotGame[];
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ games }) => {
  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingGame, setEditingGame] = useState<Partial<SlotGame> | null>(null);
  const [previewGame, setPreviewGame] = useState<SlotGame | null>(null);
  const [formErrors, setFormErrors] = useState<{ rtp?: string; volatility?: string; title?: string }>({});

  // Filter States
  const [filterProvider, setFilterProvider] = useState('All');
  const [filterDemo, setFilterDemo] = useState('All');
  const [filterRtp, setFilterRtp] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');

  // Derived Data for Filters
  const uniqueProviders = useMemo(() => {
    const p = new Set(games.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, [games]);

  // Statistics
  const slotsMissingDemo = games.filter(g => !g.demoUrl);
  const slotsMissingRtp = games.filter(g => !g.rtp || g.rtp === 0);
  const totalSlots = games.length;
  const avgRtp = totalSlots > 0 ? games.reduce((acc, g) => acc + (g.rtp || 0), 0) / totalSlots : 0;
  const providersCount = uniqueProviders.length - 1; // Subtract 'All'

  // Filtered Inventory Logic
  const filteredInventory = useMemo(() => {
    return games.filter(game => {
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;

      const hasDemo = !!game.demoUrl;
      const matchesDemo = filterDemo === 'All' || 
                         (filterDemo === 'Missing' && !hasDemo) || 
                         (filterDemo === 'Available' && hasDemo);

      const hasRtp = !!game.rtp && game.rtp !== 0;
      const matchesRtpStatus = filterRtp === 'All' || 
                              (filterRtp === 'Missing' && !hasRtp) || 
                              (filterRtp === 'Available' && hasRtp);

      const matchesStatus = filterStatus === 'All' || 
                           (filterStatus === 'Published' && game.isPublished) || 
                           (filterStatus === 'Draft' && !game.isPublished);

      return matchesProvider && matchesDemo && matchesRtpStatus && matchesStatus;
    });
  }, [games, filterProvider, filterDemo, filterRtp, filterStatus]);

  const getVolatilityStyle = (v: Volatility) => {
    switch (v) {
      case Volatility.LOW: return 'text-emerald-600 bg-emerald-50';
      case Volatility.MEDIUM: return 'text-blue-600 bg-blue-50';
      case Volatility.HIGH: return 'text-amber-600 bg-amber-50';
      case Volatility.EXTREME: return 'text-rose-600 bg-rose-50';
      default: return 'text-gray-600 bg-gray-50';
    }
  };

  const validateField = (name: string, value: any) => {
    let error = '';
    if (name === 'rtp') {
      const numValue = parseFloat(value);
      if (isNaN(numValue)) {
        error = 'RTP must be a valid number.';
      } else if (numValue < 70 || numValue > 100) {
        error = 'RTP typically ranges between 70% and 100%.';
      }
    }
    if (name === 'volatility') {
      if (!value) {
        error = 'Please select a volatility level.';
      }
    }
    if (name === 'title') {
      if (!value || value.trim().length === 0) {
        error = 'Slot name is required.';
      }
    }

    setFormErrors(prev => ({ ...prev, [name]: error }));
    return error === '';
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : (name === 'rtp' ? parseFloat(value) : value);

    setEditingGame(prev => ({ ...prev, [name]: val }));
    validateField(name, val);
  };

  const handleEdit = (game: SlotGame) => {
    setEditingGame(game);
    setFormErrors({});
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingGame({
      title: '',
      provider: '',
      rtp: 96.00,
      volatility: Volatility.MEDIUM,
      isPublished: false,
      lastUpdated: new Date().toISOString().split('T')[0]
    });
    setFormErrors({});
    setIsModalOpen(true);
  };

  const isFormValid = useMemo(() => {
    return (
      editingGame?.title && 
      !formErrors.title && 
      !formErrors.rtp && 
      !formErrors.volatility
    );
  }, [editingGame, formErrors]);

  return (
    <div className="bg-white min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <header className="mb-12">
          <div className="flex items-center gap-3 mb-4">
            <span className="px-2 py-1 bg-indigo-600 text-white text-[10px] font-bold uppercase tracking-widest rounded">Admin</span>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Analytics Command Center</h1>
          </div>
          <p className="text-gray-500 max-w-2xl leading-relaxed">
            Internal oversight dashboard for managing mathematical models and content integrity.
          </p>
        </header>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6 mb-12">
          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Active Models</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{totalSlots}</span>
              <div className="w-8 h-8 bg-indigo-50 rounded-lg flex items-center justify-center text-indigo-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2a2 2 0 00-2-2H5a2 2 0 00-2-2v2a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow ring-2 ring-amber-500/10">
            <p className="text-[10px] font-bold text-amber-600 uppercase tracking-[0.2em] mb-4">Slots Missing Demo</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{slotsMissingDemo.length}</span>
              <div className="w-8 h-8 bg-amber-50 rounded-lg flex items-center justify-center text-amber-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow ring-2 ring-rose-500/10">
            <p className="text-[10px] font-bold text-rose-600 uppercase tracking-[0.2em] mb-4">Slots Missing RTP</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{slotsMissingRtp.length}</span>
              <div className="w-8 h-8 bg-rose-50 rounded-lg flex items-center justify-center text-rose-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Average Catalog RTP</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{avgRtp.toFixed(2)}%</span>
              <div className="w-8 h-8 bg-emerald-50 rounded-lg flex items-center justify-center text-emerald-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Total Providers</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{providersCount}</span>
              <div className="w-8 h-8 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
              </div>
            </div>
          </div>
        </div>

        {/* Slots Inventory Section */}
        <section className="bg-white border border-gray-100 rounded-[2.5rem] shadow-sm overflow-hidden mb-12">
          <div className="p-8 border-b border-gray-50 flex flex-col gap-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="text-xl font-bold text-gray-900">Slot Inventory Management</h3>
                <p className="text-sm text-gray-500">Comprehensive list of all registered mathematical models.</p>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={handleAddNew}
                  className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
                >
                  + Register New Slot
                </button>
              </div>
            </div>

            {/* Filter Bar */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 pt-2">
              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Provider</label>
                <select 
                  value={filterProvider}
                  onChange={(e) => setFilterProvider(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  {uniqueProviders.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Demo Status</label>
                <select 
                  value={filterDemo}
                  onChange={(e) => setFilterDemo(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  <option value="All">All Demos</option>
                  <option value="Available">Available (✔)</option>
                  <option value="Missing">Missing (✖)</option>
                </select>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">RTP Status</label>
                <select 
                  value={filterRtp}
                  onChange={(e) => setFilterRtp(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  <option value="All">All RTP Data</option>
                  <option value="Available">Has Data (✔)</option>
                  <option value="Missing">Data Missing (✖)</option>
                </select>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Publication</label>
                <select 
                  value={filterStatus}
                  onChange={(e) => setFilterStatus(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  <option value="All">All Statuses</option>
                  <option value="Published">Published (✔)</option>
                  <option value="Draft">Draft (✖)</option>
                </select>
              </div>
            </div>
          </div>

          <div className="overflow-x-auto">
            <table className="w-full text-left border-collapse">
              <thead>
                <tr className="bg-gray-50/50">
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100">Slot Name</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100">Provider</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100">RTP</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100">Volatility</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100 text-center">Demo</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100 text-center">Pub.</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100">Updated</th>
                  <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b border-gray-100"></th>
                </tr>
              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredInventory.map(game => (
                  <tr key={game.id} className="hover:bg-gray-50/30 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <img src={game.thumbnail} className="w-10 h-7 rounded-lg object-cover border border-gray-100" alt="" />
                        <span className="text-sm font-bold text-gray-900 group-hover:text-indigo-600 transition-colors">{game.title}</span>
                      </div>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-xs font-medium text-gray-600">{game.provider}</span>
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-sm font-mono font-bold text-gray-900">
                        {game.rtp ? `${game.rtp.toFixed(2)}%` : 'N/A'}
                      </span>
                    </td>
                    <td className="px-6 py-4">
                      <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-tight border border-current ${getVolatilityStyle(game.volatility)}`}>
                        {game.volatility}
                      </span>
                    </td>
                    <td className="px-6 py-4 text-center">
                      {game.demoUrl ? (
                        <span className="text-emerald-500 font-bold" title="Demo Available">✔</span>
                      ) : (
                        <span className="text-rose-400 font-bold" title="Demo Missing">✖</span>
                      )}
                    </td>
                    <td className="px-6 py-4 text-center">
                      {game.isPublished ? (
                        <span className="text-indigo-600 font-bold" title="Published">✔</span>
                      ) : (
                        <span className="text-gray-300 font-bold" title="Draft">✖</span>
                      )}
                    </td>
                    <td className="px-6 py-4">
                      <span className="text-[10px] text-gray-400 font-medium whitespace-nowrap">{game.lastUpdated}</span>
                    </td>
                    <td className="px-6 py-4 text-right">
                      <div className="flex items-center justify-end gap-3">
                        <button 
                          onClick={() => setPreviewGame(game)}
                          className="text-gray-400 hover:text-indigo-600 text-xs font-bold transition-colors"
                        >
                          Preview
                        </button>
                        <button 
                          onClick={() => handleEdit(game)}
                          className="text-indigo-600 hover:text-indigo-800 text-xs font-bold transition-colors"
                        >
                          Edit
                        </button>
                      </div>
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>

            {filteredInventory.length === 0 && (
              <div className="py-20 text-center bg-gray-50/50">
                 <p className="text-gray-400 font-medium text-sm">No models found for these filter settings.</p>
              </div>
            )}
          </div>
        </section>

        {/* Health Checks section... */}
        <section className="bg-gray-50 rounded-[2.5rem] p-8 sm:p-12 border border-gray-100">
           <h3 className="text-lg font-bold text-gray-900 mb-6">Database Health Checks</h3>
           <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="space-y-4">
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Content Assets Missing</h4>
                {slotsMissingDemo.length > 0 ? (
                  slotsMissingDemo.map(game => (
                    <div key={game.id} className="bg-white p-4 rounded-2xl border border-gray-200 flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <img src={game.thumbnail} className="w-10 h-7 rounded object-cover" alt="" />
                        <div>
                          <p className="text-sm font-bold text-gray-900">{game.title}</p>
                          <p className="text-[10px] text-gray-400 uppercase">{game.provider}</p>
                        </div>
                      </div>
                      <span className="px-2 py-0.5 bg-amber-50 text-amber-600 text-[10px] font-bold rounded uppercase border border-amber-100 whitespace-nowrap">No Demo</span>
                    </div>
                  ))
                ) : (
                  <p className="text-gray-400 text-xs italic">All demo URLs present.</p>
                )}
              </div>

              <div className="space-y-4">
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Technical Data Missing</h4>
                {slotsMissingRtp.length > 0 ? (
                  slotsMissingRtp.map(game => (
                    <div key={game.id} className="bg-white p-4 rounded-2xl border border-gray-200 flex items-center justify-between">
                      <div className="flex items-center gap-4">
                        <img src={game.thumbnail} className="w-10 h-7 rounded object-cover" alt="" />
                        <div>
                          <p className="text-sm font-bold text-gray-900">{game.title}</p>
                          <p className="text-[10px] text-gray-400 uppercase">{game.provider}</p>
                        </div>
                      </div>
                      <span className="px-2 py-0.5 bg-rose-50 text-rose-600 text-[10px] font-bold rounded uppercase border border-rose-100 whitespace-nowrap">No RTP</span>
                    </div>
                  ))
                ) : (
                  <p className="text-gray-400 text-xs italic">All RTP values verified.</p>
                )}
              </div>
           </div>
        </section>
      </div>

      {/* Preview Modal */}
      {previewGame && (
        <GameDetailModal 
          game={previewGame} 
          onClose={() => setPreviewGame(null)} 
        />
      )}

      {/* Add/Edit Slot Modal */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm animate-in fade-in duration-300">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden relative animate-in zoom-in-95 duration-300">
            <header className="p-8 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">
                  {editingGame?.id ? 'Update Mathematical Model' : 'Register New Model'}
                </h2>
                <p className="text-sm text-gray-500">Ensure data accuracy for analytical integrity.</p>
              </div>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="p-2 hover:bg-gray-100 rounded-full transition-colors"
              >
                <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" />
                </svg>
              </button>
            </header>

            <form className="p-8 space-y-6 max-h-[70vh] overflow-y-auto" onSubmit={(e) => e.preventDefault()}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
                {/* Title */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Slot Name</label>
                  <input 
                    type="text" 
                    name="title"
                    value={editingGame?.title || ''}
                    onChange={handleInputChange}
                    placeholder="e.g. Prism Horizon"
                    className={`w-full bg-gray-50 border px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 transition-all ${
                      formErrors.title ? 'border-rose-300 focus:ring-rose-500/20 bg-rose-50/20' : 'border-gray-200 focus:ring-indigo-500/20'
                    }`}
                  />
                  {formErrors.title && (
                    <p className="text-[10px] font-bold text-rose-500 ml-1">{formErrors.title}</p>
                  )}
                </div>

                {/* Provider */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Provider</label>
                  <input 
                    type="text" 
                    name="provider"
                    value={editingGame?.provider || ''}
                    onChange={handleInputChange}
                    placeholder="e.g. NeonLogic"
                    className="w-full bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 focus:ring-indigo-500/20" 
                  />
                </div>

                {/* RTP with Tooltip and Validation */}
                <div className="space-y-1.5 relative group/tooltip">
                  <div className="flex items-center gap-1.5 ml-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Theoretical RTP (%)</label>
                    <div className="relative group/icon cursor-help">
                      <svg className="w-3 h-3 text-indigo-400" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-8-3a1 1 0 00-.867.5 1 1 0 11-1.731-1A3 3 0 0113 8a3.001 3.001 0 01-2 2.83V11a1 1 0 11-2 0v-1a1 1 0 011-1 1 1 0 100-2zm0 8a1 1 0 100-2 1 1 0 000 2z" clipRule="evenodd" />
                      </svg>
                      {/* Tooltip content */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-64 p-3 bg-gray-900 text-[10px] text-white rounded-xl shadow-2xl opacity-0 invisible group-hover/icon:opacity-100 group-hover/icon:visible transition-all z-20 pointer-events-none border border-gray-700">
                        <p className="font-bold mb-1 uppercase tracking-widest text-indigo-400">RTP Technical Meaning</p>
                        <p className="leading-relaxed">Return to Player. The theoretical percentage of total wagered money that a slot pays back to players over millions of spins. Industry standard is 96.00%.</p>
                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-gray-900" />
                      </div>
                    </div>
                  </div>
                  <input 
                    type="number" 
                    step="0.01"
                    name="rtp"
                    value={editingGame?.rtp || ''}
                    onChange={handleInputChange}
                    className={`w-full bg-gray-50 border px-4 py-3 rounded-xl text-sm font-mono text-gray-900 outline-none focus:ring-2 transition-all ${
                      formErrors.rtp ? 'border-rose-300 focus:ring-rose-500/20 bg-rose-50/20' : 'border-gray-200 focus:ring-indigo-500/20'
                    }`}
                  />
                  {formErrors.rtp && (
                    <p className="text-[10px] font-bold text-rose-500 ml-1">{formErrors.rtp}</p>
                  )}
                </div>

                {/* Volatility with Tooltip and Validation */}
                <div className="space-y-1.5 relative group/tooltip">
                  <div className="flex items-center gap-1.5 ml-1">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest">Volatility Level</label>
                    <div className="relative group/icon cursor-help">
                      <svg className="w-3 h-3 text-indigo-400" fill="currentColor" viewBox="0 0 20 20">
                        <path fillRule="evenodd" d="M18 10a8 8 0 11-16 0 8 8 0 0116 0zm-8-3a1 1 0 00-.867.5 1 1 0 11-1.731-1A3 3 0 0113 8a3.001 3.001 0 01-2 2.83V11a1 1 0 11-2 0v-1a1 1 0 011-1 1 1 0 100-2zm0 8a1 1 0 100-2 1 1 0 000 2z" clipRule="evenodd" />
                      </svg>
                      {/* Tooltip content */}
                      <div className="absolute bottom-full left-1/2 -translate-x-1/2 mb-2 w-64 p-3 bg-gray-900 text-[10px] text-white rounded-xl shadow-2xl opacity-0 invisible group-hover/icon:opacity-100 group-hover/icon:visible transition-all z-20 pointer-events-none border border-gray-700">
                        <p className="font-bold mb-1 uppercase tracking-widest text-indigo-400">Volatility Meaning</p>
                        <p className="leading-relaxed">Describes the frequency and scale of payouts. High volatility = larger but rarer wins. Low volatility = smaller but more frequent returns to extend play.</p>
                        <div className="absolute top-full left-1/2 -translate-x-1/2 border-8 border-transparent border-t-gray-900" />
                      </div>
                    </div>
                  </div>
                  <select 
                    name="volatility"
                    value={editingGame?.volatility || ''}
                    onChange={handleInputChange}
                    className={`w-full bg-gray-50 border px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 transition-all ${
                      formErrors.volatility ? 'border-rose-300 focus:ring-rose-500/20 bg-rose-50/20' : 'border-gray-200 focus:ring-indigo-500/20'
                    }`}
                  >
                    <option value="" disabled>Select Volatility</option>
                    {Object.values(Volatility).map(v => <option key={v} value={v}>{v}</option>)}
                  </select>
                  {formErrors.volatility && (
                    <p className="text-[10px] font-bold text-rose-500 ml-1">{formErrors.volatility}</p>
                  )}
                </div>
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Simulation URL (Demo)</label>
                <input 
                  type="url" 
                  name="demoUrl"
                  value={editingGame?.demoUrl || ''}
                  onChange={handleInputChange}
                  placeholder="https://..."
                  className="w-full bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 focus:ring-indigo-500/20" 
                />
              </div>

              <div className="flex items-center gap-3 p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                <input 
                  type="checkbox" 
                  name="isPublished"
                  checked={editingGame?.isPublished || false}
                  onChange={handleInputChange}
                  id="publish_check"
                  className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500" 
                />
                <label htmlFor="publish_check" className="text-sm font-bold text-indigo-900 cursor-pointer">
                  Publicly visible on the platform
                </label>
              </div>
            </form>

            <footer className="p-8 border-t border-gray-100 flex justify-end gap-3 bg-gray-50/50">
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-6 py-2.5 text-sm font-bold text-gray-500 hover:text-gray-700 transition-colors"
              >
                Discard
              </button>
              <button 
                onClick={() => setIsModalOpen(false)}
                disabled={!isFormValid}
                className={`px-8 py-2.5 text-sm font-bold rounded-xl transition-all shadow-lg ${
                  isFormValid 
                    ? 'bg-indigo-600 text-white hover:bg-indigo-700 shadow-indigo-200 cursor-pointer' 
                    : 'bg-gray-200 text-gray-400 cursor-not-allowed shadow-none'
                }`}
              >
                {editingGame?.id ? 'Save Changes' : 'Register Slot'}
              </button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

export default AdminDashboard;

import React, { useState, useMemo, useEffect } from 'react';
import Navbar from './components/Navbar';
import GameCard from './components/GameCard';
import GameDetailPage from './components/GameDetailPage';
import RTPRankings from './components/RTPRankings';
import VolatilityRankings from './components/VolatilityRankings';
import SlotComparison from './components/SlotComparison';
import AdminDashboard from './components/AdminDashboard';
import ProviderSection from './components/ProviderSection';
import EducationSection from './components/EducationSection';
import ResponsibleNotice from './components/ResponsibleNotice';
import { MOCK_GAMES } from './constants';
import { SlotGame } from './types';

type View = 'home' | 'rtp' | 'volatility' | 'compare' | 'providers' | 'guide' | 'admin';

function App() {
  const [currentView, setCurrentView] = useState<View>('home');
  const [searchQuery, setSearchQuery] = useState('');
  const [selectedGame, setSelectedGame] = useState<SlotGame | null>(null);
  const [filterProvider, setFilterProvider] = useState('All');

  useEffect(() => {
    window.scrollTo(0, 0);
  }, [selectedGame, currentView]);

  const providers = useMemo(() => {
    const p = new Set(MOCK_GAMES.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, []);

  const filteredGames = useMemo(() => {
    return MOCK_GAMES.filter(game => {
      const matchesSearch = game.title.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            game.provider.toLowerCase().includes(searchQuery.toLowerCase()) ||
                            game.description.toLowerCase().includes(searchQuery.toLowerCase());
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;
      return matchesSearch && matchesProvider;
    });
  }, [searchQuery, filterProvider]);

  const handleNavigate = (view: View) => {
    setCurrentView(view);
    setSelectedGame(null);
  };

  const renderContent = () => {
    if (selectedGame) {
      return (
        <GameDetailPage 
          game={selectedGame} 
          onBack={() => setSelectedGame(null)} 
          similarGames={MOCK_GAMES.filter(g => g.id !== selectedGame.id).slice(0, 4)}
        />
      );
    }

    switch (currentView) {
      case 'rtp':
        return <RTPRankings games={MOCK_GAMES} onSelectGame={setSelectedGame} />;
      case 'volatility':
        return <VolatilityRankings games={MOCK_GAMES} onSelectGame={setSelectedGame} />;
      case 'compare':
        return <SlotComparison games={MOCK_GAMES} onSelectGame={setSelectedGame} />;
      case 'admin':
        return <AdminDashboard games={MOCK_GAMES} />;
      case 'home':
      default:
        return (
          <>
            <header className="bg-white border-b border-gray-100 py-16 sm:py-28 overflow-hidden relative">
              <div className="absolute top-0 right-0 -mr-20 mt-10 opacity-5 pointer-events-none select-none">
                <svg width="400" height="400" viewBox="0 0 100 100" className="rotate-12">
                  <rect x="20" y="20" width="60" height="60" fill="currentColor" className="text-indigo-600" rx="10" />
                </svg>
              </div>

              <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 relative">
                <div className="max-w-4xl">
                  <div className="inline-flex items-center gap-2 px-3 py-1 rounded-full bg-indigo-50 text-indigo-600 text-[10px] font-bold uppercase tracking-widest mb-6 border border-indigo-100">
                    <span className="relative flex h-2 w-2">
                      <span className="animate-ping absolute inline-flex h-full w-full rounded-full bg-indigo-400 opacity-75"></span>
                      <span className="relative inline-flex rounded-full h-2 w-2 bg-indigo-500"></span>
                    </span>
                    Live Data Analysis Engine
                  </div>
                  <h1 className="text-4xl sm:text-5xl lg:text-7xl font-extrabold text-gray-900 tracking-tight leading-[1.1] mb-6">
                    Slot Analytics for the <span className="text-indigo-600">Informed Player.</span>
                  </h1>
                  <p className="text-lg sm:text-xl text-gray-500 mb-10 leading-relaxed font-medium">
                    Objective math models, transparent RTP tracking, and free demo play. <br className="hidden sm:block"/>No hype. Just the data you need to play smarter.
                  </p>

                  <div className="flex flex-col sm:flex-row items-stretch gap-4 max-w-3xl">
                    <div className="relative flex-grow group">
                      <div className="absolute inset-y-0 left-0 pl-5 flex items-center pointer-events-none">
                        <svg className="h-5 w-5 text-gray-400 group-focus-within:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 21l-6-6m2-5a7 7 0 11-14 0 7 7 0 0114 0z" />
                        </svg>
                      </div>
                      <input
                        type="text"
                        placeholder="Search models, providers, or mechanics..."
                        value={searchQuery}
                        onChange={(e) => setSearchQuery(e.target.value)}
                        className="block w-full pl-12 pr-4 py-5 border border-gray-200 rounded-2xl bg-white shadow-xl shadow-indigo-500/5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all text-gray-900 placeholder-gray-400"
                      />
                    </div>

                    <div className="sm:w-64 relative group">
                      <div className="absolute inset-y-0 left-0 pl-4 flex items-center pointer-events-none z-10">
                        <svg className="w-4 h-4 text-gray-400 group-focus-within:text-indigo-500 transition-colors" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 21V5a2 2 0 00-2-2H7a2 2 0 00-2 2v16m14 0h2m-2 0h-5m-9 0H3m2 0h5M9 7h1m-1 4h1m4-4h1m-1 4h1m-5 10v-5a1 1 0 011-1h2a1 1 0 011 1v5m-4 0h4" />
                        </svg>
                      </div>
                      <select 
                        value={filterProvider}
                        onChange={(e) => setFilterProvider(e.target.value)}
                        className="block w-full pl-10 pr-10 py-5 border border-gray-200 rounded-2xl bg-white shadow-xl shadow-indigo-500/5 focus:ring-4 focus:ring-indigo-500/10 focus:border-indigo-500 outline-none transition-all text-sm font-bold text-gray-700 appearance-none cursor-pointer"
                      >
                        {providers.map(p => (
                          <option key={p} value={p}>{p === 'All' ? 'All Providers' : p}</option>
                        ))}
                      </select>
                      <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none">
                        <svg className="w-4 h-4 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                          <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                        </svg>
                      </div>
                    </div>
                  </div>
                </div>
              </div>
            </header>

            <ProviderSection />

            <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-20">
              <div className="flex flex-col sm:flex-row sm:items-end justify-between gap-6 mb-12">
                <div>
                  <h2 className="text-2xl font-bold text-gray-900 mb-2">Technical Catalog</h2>
                  <p className="text-sm text-gray-500">Analysis of {filteredGames.length} active mathematical models</p>
                </div>

                <div className="flex items-center gap-2 overflow-x-auto pb-2 sm:pb-0 scrollbar-hide">
                  {providers.map(p => (
                    <button
                      key={p}
                      onClick={() => setFilterProvider(p)}
                      className={`whitespace-nowrap px-5 py-2 rounded-xl text-xs font-bold transition-all border ${
                        filterProvider === p 
                        ? 'bg-gray-900 text-white border-gray-900 shadow-lg shadow-gray-200' 
                        : 'bg-white text-gray-600 border-gray-200 hover:border-indigo-200 hover:text-indigo-600'
                      }`}
                    >
                      {p}
                    </button>
                  ))}
                </div>
              </div>

              {filteredGames.length > 0 ? (
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-8">
                  {filteredGames.map(game => (
                    <GameCard 
                      key={game.id} 
                      game={game} 
                      onClick={setSelectedGame} 
                    />
                  ))}
                </div>
              ) : (
                <div className="text-center py-24 bg-white rounded-[2rem] border border-dashed border-gray-200">
                   <p className="text-gray-900 font-bold mb-1">No matches found</p>
                   <p className="text-gray-500 text-sm mb-6">Try adjusting your search terms or provider selection.</p>
                   <button 
                     onClick={() => { setSearchQuery(''); setFilterProvider('All'); }}
                     className="px-6 py-2 bg-indigo-50 text-indigo-600 text-xs font-bold rounded-lg hover:bg-indigo-100 transition-colors"
                   >
                     Reset Dashboard
                   </button>
                </div>
              )}
            </main>
            <EducationSection />
          </>
        );
    }
  };

  return (
    <div className="min-h-screen bg-[#f9fafb]">
      <Navbar currentView={currentView} onNavigate={handleNavigate} />

      {renderContent()}

      <ResponsibleNotice />

      <footer className="bg-white border-t border-gray-100 py-12">
        <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
          <div className="flex flex-col md:flex-row justify-between items-center gap-6">
            <div className="flex items-center gap-2">
              <div className="w-6 h-6 bg-indigo-600 rounded flex items-center justify-center">
                <span className="text-white font-bold text-[10px]">S</span>
              </div>
              <span className="text-lg font-bold tracking-tight text-gray-900">SpinStacks</span>
            </div>
            <p className="text-xs text-gray-400">© 2024 SpinStacks Analytics. Independent data for the informed player.</p>
          </div>
        </div>
      </footer>
    </div>
  );
}

export default App;

export enum Volatility {
  LOW = 'Low',
  MEDIUM = 'Medium',
  HIGH = 'High',
  EXTREME = 'Extreme'
}

export interface SlotGame {
  id: string;
  title: string;
  slug: string;
  provider: string;
  rtp: number;
  volatility: Volatility;
  maxWin: string;
  reels: string;
  paylines: string;
  releaseDate: string;
  thumbnail: string;
  description: string;
  availableAt: string[];
  demoUrl?: string;
  isPublished: boolean; // For admin tracking
  lastUpdated: string;  // For admin tracking
}

export interface GameInsight {
  summary: string;
  pros: string[];
  cons: string[];
  strategyScore: number;
}

import React, { useState, useMemo, useEffect } from 'react';
import { SlotGame, Volatility } from '../types';
import GameDetailModal from './GameDetailModal';

interface AdminDashboardProps {
  games: SlotGame[];
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ games }) => {
  // UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingGame, setEditingGame] = useState<Partial<SlotGame> | null>(null);
  const [previewGame, setPreviewGame] = useState<SlotGame | null>(null);
  const [formErrors, setFormErrors] = useState<{ rtp?: string; volatility?: string; title?: string; slug?: string }>({});
  const [isSlugDirty, setIsSlugDirty] = useState(false);

  // Filter States
  const [filterProvider, setFilterProvider] = useState('All');
  const [filterDemo, setFilterDemo] = useState('All');
  const [filterRtp, setFilterRtp] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');

  // Derived Data for Filters
  const uniqueProviders = useMemo(() => {
    const p = new Set(games.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, [games]);

  // Statistics
  const slotsMissingDemo = games.filter(g => !g.demoUrl);
  const slotsMissingRtp = games.filter(g => !g.rtp || g.rtp === 0);
  const totalSlots = games.length;
  const avgRtp = totalSlots > 0 ? games.reduce((acc, g) => acc + (g.rtp || 0), 0) / totalSlots : 0;
  const providersCount = uniqueProviders.length - 1; // Subtract 'All'

  // Filtered Inventory Logic
  const filteredInventory = useMemo(() => {
    return games.filter(game => {
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;

      const hasDemo = !!game.demoUrl;
      const matchesDemo = filterDemo === 'All' || 
                         (filterDemo === 'Missing' && !hasDemo) || 
                         (filterDemo === 'Available' && hasDemo);

      const hasRtp = !!game.rtp && game.rtp !== 0;
      const matchesRtpStatus = filterRtp === 'All' || 
                              (filterRtp === 'Missing' && !hasRtp) || 
                              (filterRtp === 'Available' && hasRtp);

      const matchesStatus = filterStatus === 'All' || 
                           (filterStatus === 'Published' && game.isPublished) || 
                           (filterStatus === 'Draft' && !game.isPublished);

      return matchesProvider && matchesDemo && matchesRtpStatus && matchesStatus;
    });
  }, [games, filterProvider, filterDemo, filterRtp, filterStatus]);

  const getVolatilityStyle = (v: Volatility) => {
    switch (v) {
      case Volatility.LOW: return 'text-emerald-600 bg-emerald-50';
      case Volatility.MEDIUM: return 'text-blue-600 bg-blue-50';
      case Volatility.HIGH: return 'text-amber-600 bg-amber-50';
      case Volatility.EXTREME: return 'text-rose-600 bg-rose-50';
      default: return 'text-gray-600 bg-gray-50';
    }
  };

  const slugify = (text: string) => 
    text.toLowerCase()
      .trim()
      .replace(/[^\w\s-]/g, '')
      .replace(/[\s_-]+/g, '-')
      .replace(/^-+|-+$/g, '');

  const validateField = (name: string, value: any) => {
    let error = '';
    if (name === 'rtp') {
      const numValue = parseFloat(value);
      if (isNaN(numValue)) {
        error = 'RTP must be a valid number.';
      } else if (numValue < 70 || numValue > 100) {
        error = 'RTP typically ranges between 70% and 100%.';
      }
    }
    if (name === 'volatility') {
      if (!value) {
        error = 'Please select a volatility level.';
      }
    }
    if (name === 'title') {
      if (!value || value.trim().length === 0) {
        error = 'Slot name is required.';
      }
    }
    if (name === 'slug') {
      if (!value || value.trim().length === 0) {
        error = 'URL slug is required.';
      } else if (!/^[a-z0-9-]+$/.test(value)) {
        error = 'Slug must be lowercase alphanumeric and hyphens only.';
      }
    }

    setFormErrors(prev => ({ ...prev, [name]: error }));
    return error === '';
  };

  const handleInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value, type } = e.target;
    const val = type === 'checkbox' ? (e.target as HTMLInputElement).checked : (name === 'rtp' ? parseFloat(value) : value);

    if (name === 'slug') {
      setIsSlugDirty(true);
    }

    setEditingGame(prev => {
      const newState = { ...prev, [name]: val };
      if (name === 'title' && !isSlugDirty) {
        newState.slug = slugify(value);
      }
      return newState;
    });

    validateField(name, val);

    if (name === 'title' && !isSlugDirty) {
      validateField('slug', slugify(value));
    }
  };

  const handleEdit = (game: SlotGame) => {
    setEditingGame(game);
    setFormErrors({});
    setIsSlugDirty(true);
    setIsModalOpen(true);
  };

  const handleAddNew = () => {
    setEditingGame({
      title: '',
      slug: '',
      provider: '',
      rtp: 96.00,
      volatility: Volatility.MEDIUM,
      isPublished: false,
      lastUpdated: new Date().toISOString().split('T')[0]
    });
    setFormErrors({});
    setIsSlugDirty(false);
    setIsModalOpen(true);
  };

  const isFormValid = useMemo(() => {
    return (
      editingGame?.title && 
      editingGame?.slug &&
      !formErrors.title && 
      !formErrors.slug &&
      !formErrors.rtp && 
      !formErrors.volatility
    );
  }, [editingGame, formErrors]);

  return (
    <div className="bg-white min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <header className="mb-12">
          <div className="flex items-center gap-3 mb-4">
            <span className="px-2 py-1 bg-indigo-600 text-white text-[10px] font-bold uppercase tracking-widest rounded">Admin</span>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">Analytics Command Center</h1>
          </div>
          <p className="text-gray-500 max-w-2xl leading-relaxed">
            Internal oversight dashboard for managing mathematical models and content integrity.
          </p>
        </header>

        {/* Stats Cards */}
        <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-3 xl:grid-cols-5 gap-6 mb-12">
          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Active Models</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{totalSlots}</span>
              <div className="w-8 h-8 bg-indigo-50 rounded-lg flex items-center justify-center text-indigo-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 17v-2a2 2 0 00-2-2H5a2 2 0 00-2-2v2a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow ring-2 ring-amber-500/10">
            <p className="text-[10px] font-bold text-amber-600 uppercase tracking-[0.2em] mb-4">Slots Missing Demo</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{slotsMissingDemo.length}</span>
              <div className="w-8 h-8 bg-amber-50 rounded-lg flex items-center justify-center text-amber-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M12 9v2m0 4h.01m-6.938 4h13.856c1.54 0 2.502-1.667 1.732-3L13.732 4c-.77-1.333-2.694-1.333-3.464 0L3.34 16c-.77 1.333.192 3 1.732 3z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow ring-2 ring-rose-500/10">
            <p className="text-[10px] font-bold text-rose-600 uppercase tracking-[0.2em] mb-4">Slots Missing RTP</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{slotsMissingRtp.length}</span>
              <div className="w-8 h-8 bg-rose-50 rounded-lg flex items-center justify-center text-rose-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M9 19v-6a2 2 0 00-2-2H5a2 2 0 00-2 2v6a2 2 0 002 2h2a2 2 0 002-2zm0 0V9a2 2 0 012-2h2a2 2 0 012 2v10m-6 0a2 2 0 002 2h2a2 2 0 002-2m0 0V5a2 2 0 012-2h2a2 2 0 012 2v14a2 2 0 01-2 2h-2a2 2 0 01-2-2z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Average Catalog RTP</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{avgRtp.toFixed(2)}%</span>
              <div className="w-8 h-8 bg-emerald-50 rounded-lg flex items-center justify-center text-emerald-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M7 12l3-3 3 3 4-4M8 21l4-4 4 4M3 4h18M4 4h16v12a1 1 0 01-1 1H5a1 1 0 01-1-1V4z" />
                </svg>
              </div>
            </div>
          </div>

          <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm hover:shadow-md transition-shadow">
            <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Total Providers</p>
            <div className="flex items-end justify-between">
              <span className="text-4xl font-extrabold text-gray-900">{providersCount}</span>
              <div className="w-8 h-8 bg-blue-50 rounded-lg flex items-center justify-center text-blue-600">
                <svg className="w-5 h-5" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                  <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M21 13.255A23.931 23.931 0 0112 15c-3.183 0-6.22-.62-9-1.745M16 6V4a2 2 0 00-2-2h-4a2 2 0 00-2 2v2m4 6h.01M5 20h14a2 2 0 002-2V8a2 2 0 00-2-2H5a2 2 0 00-2 2v10a2 2 0 002 2z" />
                </svg>
              </div>
            </div>
          </div>
        </div>

        {/* Slots Inventory Section */}
        <section className="bg-white border border-gray-100 rounded-[2.5rem] shadow-sm overflow-hidden mb-12">
          <div className="p-8 border-b border-gray-50 flex flex-col gap-6">
            <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="text-xl font-bold text-gray-900">Slot Inventory Management</h3>
                <p className="text-sm text-gray-500">Comprehensive list of all registered mathematical models.</p>
              </div>
              <div className="flex gap-2">
                <button 
                  onClick={handleAddNew}
                  className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-200"
                >
                  + Register New Slot
                </button>
              </div>
            </div>

            {/* Filter Bar */}
            <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 pt-2">
              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Provider</label>
                <select 
                  value={filterProvider}
                  onChange={(e) => setFilterProvider(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  {uniqueProviders.map(p => <option key={p} value={p}>{p}</option>)}
                </select>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Demo Status</label>
                <select 
                  value={filterDemo}
                  onChange={(e) => setFilterDemo(e.target.value)}
                  className="w-full bg-gray-50 border border-gray-200 px-3 py-2.5 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                >
                  <option value="All">All Demos</option>
                  <option value="Available">Available (✔)</option>
                  <option value="Missing">Missing (✖)</option>
                </select>
              </div>

              <div className="flex flex-col gap-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">RTP Status</label>
                <select 
                  value={filterRtp}
                  onChange={(e) => setFilterRtp(e.target.value)}
