              </thead>
              <tbody className="divide-y divide-gray-50">
                {filteredInventory.map(game => (
                  <tr key={game.id} className="hover:bg-gray-50/30 transition-colors group">
                    <td className="px-6 py-4">
                      <div className="flex items-center gap-3">
                        <img src={game.thumbnail} className="w-10 h-7 rounded-lg object-cover border border-gray-100" alt="" />
