        </section>

        {/* Health Checks section... */}
        <section className="bg-gray-50 rounded-[2.5rem] p-8 sm:p-12 border border-gray-100">
           <h3 className="text-lg font-bold text-gray-900 mb-6">Database Health Checks</h3>
           <div className="grid grid-cols-1 lg:grid-cols-2 gap-8">
              <div className="space-y-4">
                <h4 className="text-xs font-bold text-gray-400 uppercase tracking-widest mb-4">Content Assets Missing</h4>
