                    </div>
                    <input 
                      type="url" 
                      placeholder="https://..."
                      value={editingProvider?.logoUrl || ''} 
                      onChange={e => setEditingProvider({...editingProvider!, logoUrl: e.target.value})}
                      className="flex-grow bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm" 
                    />
