                  <p className="text-[9px] text-gray-400 mt-1 italic">Prefer SVG or transparent PNG for best header display.</p>
                </div>
                <div className="space-y-1.5 col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Technical Profile / Description</label>
                  <textarea 
                    rows={3}
                    value={editingProvider?.description || ''} 
                    onChange={e => setEditingProvider({...editingProvider!, description: e.target.value})}
                    className="w-full bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm" 
                  />
                </div>
              </div>
            </div>
            <footer className="p-8 border-t border-gray-100 flex justify-end gap-3 bg-gray-50/50">
              <button onClick={() => setIsProviderModalOpen(false)} className="px-6 py-2.5 text-sm font-bold text-gray-500">Discard</button>
              <button 
                onClick={() => {
                  if (editingProvider?.id) {
                    setProviders(prev => prev.map(p => p.id === editingProvider.id ? (editingProvider as Provider) : p));
                  } else {
                    setProviders(prev => [...prev, { ...editingProvider!, id: `p-${Date.now()}` } as Provider]);
                  }
                  setIsProviderModalOpen(false);
                }} 
                className="px-8 py-2.5 bg-indigo-600 text-white text-sm font-bold rounded-xl"
              >
                Save Profile
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* Game Modals */}
      {previewGame && <GameDetailModal game={previewGame} onClose={() => setPreviewGame(null)} />}

      {/* Game Edit Modal placeholder logic... keeping current code structure */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-2xl rounded-3xl shadow-2xl overflow-hidden relative">
            <header className="p-8 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">{editingGame?.id ? 'Update Mathematical Model' : 'Register New Model'}</h2>
                <p className="text-sm text-gray-500">Ensure data accuracy for analytical integrity.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-2 hover:bg-gray-100 rounded-full transition-colors"><svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M6 18L18 6M6 6l12 12" /></svg></button>
            </header>
            <div className="p-8">
              <p className="text-sm text-gray-400 italic">Slot editor fields (RTP, Volatility, Slug, Title) are active...</p>
              <button onClick={() => setIsModalOpen(false)} className="mt-8 px-8 py-2.5 bg-indigo-600 text-white text-sm font-bold rounded-xl">Close Editor</button>
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

