import React, { useState, useEffect } from 'react';
import { SlotGame, GameInsight } from '../types';
import { getGameInsights } from '../services/geminiService';
import SlotHeader from './SlotHeader';
import SlotDemo from './SlotDemo';
import SlotStatsCard from './SlotStatsCard';
import SlotTabs from './SlotTabs';
import WhereToPlay from './WhereToPlay';
import SimilarSlots from './SimilarSlots';
import ResponsibleNotice from './ResponsibleNotice';

interface GameDetailPageProps {
  game: SlotGame;
  onBack: () => void;
  similarGames: SlotGame[];
}

const GameDetailPage: React.FC<GameDetailPageProps> = ({ game, onBack, similarGames }) => {
  const [insights, setInsights] = useState<GameInsight | null>(null);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    const fetchInsights = async () => {
      setLoading(true);
      const data = await getGameInsights(game);
      setInsights(data);
      setLoading(false);
    };
    fetchInsights();
  }, [game]);

  // Transform game.availableAt strings into Casino objects for WhereToPlay
  const casinos = game.availableAt.map((name) => ({
    name,
    license: 'MGA/B2C/123/2024', // Mock license
    slug: name.toLowerCase().replace(/\s+/g, '-'),
  }));

  // Transform similarGames into SimilarSlot objects
  const formattedSimilarSlots = similarGames.map((g) => ({
    name: g.title,
    provider: g.provider,
    slug: g.id,
    thumbnail: g.thumbnail,
  }));

  const overviewContent = (
    <div className="space-y-4">
      <p className="text-gray-600 leading-relaxed">{game.description}</p>
      <div className="p-4 bg-gray-50 rounded-xl border border-gray-100">
        <h5 className="text-xs font-bold text-gray-900 uppercase tracking-widest mb-2">Technical Description</h5>
        <p className="text-sm text-gray-500 italic">
          This model utilizes a {game.reels} reel set with {game.paylines} active evaluation paths. 
          RNG outcomes are generated server-side and transmitted via secure socket layers.
        </p>
      </div>
    </div>
  );

  const rtpContent = (
    <div className="space-y-6">
      {loading ? (
        <div className="animate-pulse space-y-3">
          <div className="h-4 bg-gray-100 rounded w-3/4"></div>
          <div className="h-4 bg-gray-100 rounded w-1/2"></div>
        </div>
      ) : (
        <>
          <p className="text-gray-600 italic">"{insights?.summary}"</p>
          <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
            <div className="p-4 bg-emerald-50 rounded-xl border border-emerald-100">
              <span className="text-[10px] font-bold text-emerald-700 uppercase mb-2 block">Strengths</span>
              <ul className="space-y-1">
                {insights?.pros.map((p, i) => (
                  <li key={i} className="text-xs text-gray-600 flex gap-2">
                    <span className="text-emerald-500">✓</span> {p}
                  </li>
                ))}
              </ul>
            </div>
            <div className="p-4 bg-rose-50 rounded-xl border border-rose-100">
              <span className="text-[10px] font-bold text-rose-700 uppercase mb-2 block">Risk Factors</span>
              <ul className="space-y-1">
                {insights?.cons.map((c, i) => (
                  <li key={i} className="text-xs text-gray-600 flex gap-2">
                    <span className="text-rose-500">!</span> {c}
                  </li>
                ))}
              </ul>
            </div>
          </div>
          <div className="pt-4 border-t border-gray-100">
            <div className="flex items-center justify-between mb-2">
              <span className="text-xs font-bold text-gray-400 uppercase">Strategy/Skill Influence</span>
              <span className="text-sm font-bold text-indigo-600">{insights?.strategyScore}%</span>
            </div>
            <div className="h-2 w-full bg-gray-100 rounded-full overflow-hidden">
              <div 
                className="h-full bg-indigo-500 transition-all duration-1000" 
                style={{ width: `${insights?.strategyScore}%` }}
              />
            </div>
          </div>
        </>
      )}
    </div>
  );

  const howToPlayContent = (
    <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
      <div>
        <h4 className="font-bold text-gray-900 mb-2">Core Mechanics</h4>
        <p className="text-sm text-gray-500">
          Symbols are evaluated based on the {game.paylines} path logic. Adjusting bet sizes does not affect the 
          underlying RNG probabilities but does scale the payout table proportionally.
        </p>
      </div>
      <div>
        <h4 className="font-bold text-gray-900 mb-2">Feature Triggers</h4>
        <p className="text-sm text-gray-500">
          The bonus simulation is triggered via specific mathematical variance spikes. Review the game's internal 
          paytable for detailed weighting of high-value symbols.
        </p>
      </div>
    </div>
  );

  return (
    <div className="min-h-screen bg-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 pt-8 pb-24 space-y-12">
        {/* Breadcrumbs / Back Navigation */}
        <nav className="flex items-center gap-4">
          <button 
            onClick={onBack}
            className="group flex items-center gap-2 text-sm font-bold text-gray-400 hover:text-indigo-600 transition-colors"
          >
            <svg className="w-4 h-4 transition-transform group-hover:-translate-x-1" fill="none" stroke="currentColor" viewBox="0 0 24 24">
              <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M10 19l-7-7m0 0l7-7m-7 7h18" />
            </svg>
            Technical Directory
          </button>
          <span className="text-gray-200">/</span>
          <span className="text-sm font-bold text-gray-900">{game.title}</span>
        </nav>

        {/* Page Sections */}
        <div className="grid grid-cols-1 lg:grid-cols-12 gap-12 items-start">
          <div className="lg:col-span-8 space-y-12">
            <SlotHeader 
              slotName={game.title}
              providerName={game.provider}
              providerSlug={game.provider.toLowerCase().replace(/\s+/g, '-')}
              releaseYear={game.releaseYear}
              category="High-Variance Simulation"
            />

            <SlotDemo 
              demoUrl="https://example.com/demo-placeholder" // In a real app, this would be a dynamic URL
              slotName={game.title}
            />

            <SlotTabs 
              overviewContent={overviewContent}
              rtpContent={rtpContent}
              howToPlayContent={howToPlayContent}
            />
          </div>

          <aside className="lg:col-span-4 space-y-12 lg:sticky lg:top-24">
            <SlotStatsCard 
              rtp={`${game.rtp}%`}
              volatility={game.volatility.toLowerCase()}
              maxWin={game.maxWin}
              paylines={game.paylines}
              provider={game.provider}
            />

            <WhereToPlay casinos={casinos} />
          </aside>
        </div>

        <SimilarSlots slots={formattedSimilarSlots} />
      </div>

      <ResponsibleNotice />
    </div>
  );
};

export default GameDetailPage;

import React, { useState, useMemo, useEffect } from 'react';
import { SlotGame, Volatility, Provider } from '../types';
import GameDetailModal from './GameDetailModal';
import { MOCK_PROVIDERS } from '../constants';

interface AdminDashboardProps {
  games: SlotGame[];
}

const AdminDashboard: React.FC<AdminDashboardProps> = ({ games }) => {
  // Navigation
  const [activeTab, setActiveTab] = useState<'slots' | 'providers'>('slots');

  // Slots UI States
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [editingGame, setEditingGame] = useState<Partial<SlotGame> | null>(null);
  const [previewGame, setPreviewGame] = useState<SlotGame | null>(null);
  const [formErrors, setFormErrors] = useState<{ rtp?: string; volatility?: string; title?: string; slug?: string; logoUrl?: string; releaseYear?: string }>({});
  const [isSlugDirty, setIsSlugDirty] = useState(false);

  // Providers UI States
  const [providers, setProviders] = useState<Provider[]>(MOCK_PROVIDERS);
  const [isProviderModalOpen, setIsProviderModalOpen] = useState(false);
  const [editingProvider, setEditingProvider] = useState<Partial<Provider> | null>(null);

  // Filter States
  const [filterProvider, setFilterProvider] = useState('All');
  const [filterDemo, setFilterDemo] = useState('All');
  const [filterRtp, setFilterRtp] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');

  // Derived Data for Filters
  const uniqueProvidersNames = useMemo(() => {
    const p = new Set(games.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, [games]);

  // Statistics
  const slotsMissingDemo = games.filter(g => !g.demoUrl);
  const slotsMissingRtp = games.filter(g => !g.rtp || g.rtp === 0);
  const totalSlots = games.length;
  const avgRtp = totalSlots > 0 ? games.reduce((acc, g) => acc + (g.rtp || 0), 0) / totalSlots : 0;
  const providersCount = providers.length;

  // Filtered Inventory Logic
  const filteredInventory = useMemo(() => {
    return games.filter(game => {
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;
      const matchesDemo = filterDemo === 'All' || (filterDemo === 'Missing' && !game.demoUrl) || (filterDemo === 'Available' && !!game.demoUrl);
      const matchesRtpStatus = filterRtp === 'All' || (filterRtp === 'Missing' && (!game.rtp || game.rtp === 0)) || (filterRtp === 'Available' && !!game.rtp);
      const matchesStatus = filterStatus === 'All' || (filterStatus === 'Published' && game.isPublished) || (filterStatus === 'Draft' && !game.isPublished);
      return matchesProvider && matchesDemo && matchesRtpStatus && matchesStatus;
    });
  }, [games, filterProvider, filterDemo, filterRtp, filterStatus]);

  const slugify = (text: string) => text.toLowerCase().trim().replace(/[^\w\s-]/g, '').replace(/[\s_-]+/g, '-').replace(/^-+|-+$/g, '');

  const handleEditGame = (game: SlotGame) => {
    setEditingGame(game);
    setFormErrors({});
    setIsSlugDirty(true);
    setIsModalOpen(true);
  };

  const handleAddNewGame = () => {
    setEditingGame({ 
      title: '', 
      slug: '', 
      provider: '', 
      rtp: 96.00, 
      volatility: Volatility.MEDIUM, 
      isPublished: false, 
      releaseYear: new Date().getFullYear(),
      lastUpdated: new Date().toISOString().split('T')[0] 
    });
    setFormErrors({});
    setIsSlugDirty(false);
    setIsModalOpen(true);
  };

  const handleEditProvider = (provider: Provider) => {
    setEditingProvider(provider);
    setIsProviderModalOpen(true);
  };

  const handleAddNewProvider = () => {
    setEditingProvider({ name: '', slug: '', logoUrl: '', description: '' });
    setIsProviderModalOpen(true);
  };

  const validateField = (name: string, value: any) => {
    let error = '';
    if (name === 'rtp') {
      const numValue = parseFloat(value);
      if (isNaN(numValue)) error = 'RTP must be a valid number.';
      else if (numValue < 70 || numValue > 100) error = 'RTP typically ranges between 70% and 100%.';
    }
    if (name === 'releaseYear') {
      const year = parseInt(value);
      const currentYear = new Date().getFullYear();
      if (isNaN(year)) error = 'Release year must be a number.';
      else if (year < 1970 || year > currentYear + 2) error = 'Please enter a valid release year.';
    }
    if (name === 'title' && (!value || value.trim().length === 0)) error = 'Slot name is required.';
    if (name === 'slug' && (!value || value.trim().length === 0 || !/^[a-z0-9-]+$/.test(value))) error = 'URL slug is required and must be URL-friendly.';

    setFormErrors(prev => ({ ...prev, [name]: error }));
  };

  const handleGameInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement>) => {
    const { name, value } = e.target;
    let finalValue: any = value;

    if (name === 'rtp') finalValue = parseFloat(value) || 0;
    if (name === 'releaseYear') finalValue = parseInt(value) || 0;
    if (name === 'isPublished') finalValue = (e.target as HTMLInputElement).checked;

    setEditingGame(prev => {
      const newState = { ...prev, [name]: finalValue };
      if (name === 'title' && !isSlugDirty) {
        newState.slug = slugify(value);
      }
      return newState;
    });

    validateField(name, finalValue);
    if (name === 'title' && !isSlugDirty) {
      validateField('slug', slugify(value));
    }
  };

  return (
    <div className="bg-white min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <header className="mb-12">
          <div className="flex items-center gap-3 mb-4">
            <span className="px-2 py-1 bg-indigo-600 text-white text-[10px] font-bold uppercase tracking-widest rounded">Admin</span>
            <h1 className="text-3xl font-extrabold text-gray-900 tracking-tight">System Registry</h1>
          </div>

          <div className="flex gap-8 border-b border-gray-100">
            <button 
              onClick={() => setActiveTab('slots')}
              className={`pb-4 text-sm font-bold transition-all ${activeTab === 'slots' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}
            >
              Slot Inventory
            </button>
            <button 
              onClick={() => setActiveTab('providers')}
              className={`pb-4 text-sm font-bold transition-all ${activeTab === 'providers' ? 'text-indigo-600 border-b-2 border-indigo-600' : 'text-gray-400 hover:text-gray-600'}`}
            >
              Certified Providers
            </button>
          </div>
        </header>

        {activeTab === 'slots' ? (
          <>
            {/* Stats Cards */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-12">
              <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Total Slots</p>
                <span className="text-4xl font-extrabold text-gray-900">{totalSlots}</span>
              </div>
              <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Average Catalog RTP</p>
                <span className="text-4xl font-extrabold text-gray-900">{avgRtp.toFixed(2)}%</span>
              </div>
              <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm ring-2 ring-amber-500/10">
                <p className="text-[10px] font-bold text-amber-600 uppercase tracking-[0.2em] mb-4">Missing Demos</p>
                <span className="text-4xl font-extrabold text-gray-900">{slotsMissingDemo.length}</span>
              </div>
              <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm ring-2 ring-rose-500/10">
                <p className="text-[10px] font-bold text-rose-600 uppercase tracking-[0.2em] mb-4">Missing RTP</p>
                <span className="text-4xl font-extrabold text-gray-900">{slotsMissingRtp.length}</span>
              </div>
              <div className="bg-white border border-gray-100 p-6 rounded-3xl shadow-sm">
                <p className="text-[10px] font-bold text-gray-400 uppercase tracking-[0.2em] mb-4">Active Providers</p>
                <span className="text-4xl font-extrabold text-gray-900">{providersCount}</span>
              </div>
            </div>

            <section className="bg-white border border-gray-100 rounded-[2.5rem] shadow-sm overflow-hidden mb-12">
              <div className="p-8 border-b border-gray-50 flex flex-col gap-6">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-4">
                  <div>
                    <h3 className="text-xl font-bold text-gray-900">Slot Inventory Management</h3>
                    <p className="text-sm text-gray-500">Manage all technical models and asset availability.</p>
                  </div>
                  <button 
                    onClick={handleAddNewGame}
                    className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-colors shadow-lg shadow-indigo-100"
                  >
                    + New Slot
                  </button>
                </div>

                {/* Filter Registry Bar */}
                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4">
                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Provider</label>
                    <select 
                      value={filterProvider}
                      onChange={(e) => setFilterProvider(e.target.value)}
                      className="w-full bg-gray-50 border border-gray-200 px-3 py-2 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                    >
                      {uniqueProvidersNames.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Asset Status (Demo)</label>
                    <select 
                      value={filterDemo}
                      onChange={(e) => setFilterDemo(e.target.value)}
                      className="w-full bg-gray-50 border border-gray-200 px-3 py-2 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                    >
                      <option value="All">All Assets</option>
                      <option value="Available">Available (✔)</option>
                      <option value="Missing">Missing (✖)</option>
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Data Status (RTP)</label>
                    <select 
                      value={filterRtp}
                      onChange={(e) => setFilterRtp(e.target.value)}
                      className="w-full bg-gray-50 border border-gray-200 px-3 py-2 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                    >
                      <option value="All">All Data</option>
                      <option value="Available">Valid (✔)</option>
                      <option value="Missing">Missing (✖)</option>
                    </select>
                  </div>

                  <div className="space-y-1.5">
                    <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Publication</label>
                    <select 
                      value={filterStatus}
                      onChange={(e) => setFilterStatus(e.target.value)}
                      className="w-full bg-gray-50 border border-gray-200 px-3 py-2 rounded-xl text-xs font-bold text-gray-700 outline-none focus:ring-2 focus:ring-indigo-500/20"
                    >
                      <option value="All">All Statuses</option>
                      <option value="Published">Published (✔)</option>
                      <option value="Draft">Draft (✖)</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-gray-50/50">
                    <tr>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">Slot Name</th>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">Provider</th>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b text-center">Demo</th>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">RTP</th>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b text-center">Status</th>
                      <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-50">
                    {filteredInventory.map(game => (
                      <tr key={game.id} className="hover:bg-gray-50/30 transition-colors">
                        <td className="px-6 py-4 text-sm font-bold text-gray-900">{game.title}</td>
                        <td className="px-6 py-4 text-xs text-gray-500">{game.provider}</td>
                        <td className="px-6 py-4 text-center">
                          {game.demoUrl ? (
                            <span className="text-emerald-500">✔</span>
                          ) : (
                            <span className="text-rose-400">✖</span>
                          )}
                        </td>
                        <td className="px-6 py-4 text-sm font-mono">{game.rtp.toFixed(2)}%</td>
                        <td className="px-6 py-4 text-center">
                          <span className={`px-2 py-0.5 rounded text-[9px] font-bold uppercase tracking-tight ${game.isPublished ? 'bg-indigo-50 text-indigo-600' : 'bg-gray-100 text-gray-400'}`}>
                            {game.isPublished ? 'Published' : 'Draft'}
                          </span>
                        </td>
                        <td className="px-6 py-4 text-right flex justify-end gap-3">
                          <button onClick={() => setPreviewGame(game)} className="text-xs font-bold text-gray-400 hover:text-indigo-600">Preview</button>
                          <button onClick={() => handleEditGame(game)} className="text-xs font-bold text-indigo-600 hover:text-indigo-800">Edit</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
                {filteredInventory.length === 0 && (
                  <div className="py-20 text-center text-gray-400 text-sm">
                    No models found matching these criteria.
                  </div>
                )}
              </div>
            </section>
          </>
        ) : (
          <section className="bg-white border border-gray-100 rounded-[2.5rem] shadow-sm overflow-hidden mb-12">
            <div className="p-8 border-b border-gray-50 flex flex-col md:flex-row md:items-center justify-between gap-4">
              <div>
                <h3 className="text-xl font-bold text-gray-900">Certified Providers Registry</h3>
                <p className="text-sm text-gray-500">Manage developer profiles and brand assets.</p>
              </div>
              <button 
                onClick={handleAddNewProvider}
                className="px-4 py-2 bg-indigo-600 text-white text-xs font-bold rounded-xl hover:bg-indigo-700 transition-colors"
              >
                + New Provider
              </button>
            </div>

            <div className="overflow-x-auto">
              <table className="w-full text-left border-collapse">
                <thead className="bg-gray-50/50">
                  <tr>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">Logo</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">Developer</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b">Slug</th>
                    <th className="px-6 py-4 text-[10px] font-bold text-gray-400 uppercase tracking-widest border-b text-right">Actions</th>
                  </tr>
                </thead>
                <tbody className="divide-y divide-gray-50">
                  {providers.map(p => (
                    <tr key={p.id} className="hover:bg-gray-50/30 transition-colors">
                      <td className="px-6 py-4">
                        <div className="w-10 h-10 rounded-lg bg-indigo-50 border border-gray-100 overflow-hidden">
                          {p.logoUrl ? (
                            <img src={p.logoUrl} alt="" className="w-full h-full object-cover" />
                          ) : (
                            <div className="w-full h-full flex items-center justify-center text-indigo-300 text-xs font-bold">
                              {p.name.charAt(0)}
                            </div>
                          )}
                        </div>
                      </td>
                      <td className="px-6 py-4">
                        <span className="text-sm font-bold text-gray-900">{p.name}</span>
                        <p className="text-[10px] text-gray-400 truncate max-w-xs">{p.description}</p>
                      </td>
                      <td className="px-6 py-4 text-xs font-mono text-gray-500">{p.slug}</td>
                      <td className="px-6 py-4 text-right">
                        <button onClick={() => handleEditProvider(p)} className="text-xs font-bold text-indigo-600 hover:text-indigo-800">Manage Assets</button>
                      </td>
                    </tr>
                  ))}
                </tbody>
              </table>
            </div>
          </section>
        )}
      </div>

      {/* Provider Edit Modal */}
      {isProviderModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/40 backdrop-blur-sm">
          <div className="bg-white w-full max-w-xl rounded-3xl shadow-2xl overflow-hidden relative">
            <header className="p-8 border-b border-gray-100 flex items-center justify-between">
              <div>
                <h2 className="text-2xl font-bold text-gray-900">{editingProvider?.id ? 'Manage Provider Assets' : 'New Developer Registration'}</h2>
                <p className="text-sm text-gray-500">Configure brand and technical identity.</p>
              </div>
              <button onClick={() => setIsProviderModalOpen(false)} className="p-2 hover:bg-gray-100 rounded-full">
                <svg className="w-6 h-6 text-gray-400" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </header>
            <div className="p-8 space-y-6">
              <div className="grid grid-cols-2 gap-4">
                <div className="space-y-1.5 col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Provider Name</label>
                  <input 
                    type="text" 
                    value={editingProvider?.name || ''} 
                    onChange={e => setEditingProvider({...editingProvider!, name: e.target.value, slug: slugify(e.target.value)})}
                    className="w-full bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm" 
                  />
                </div>
                <div className="space-y-1.5 col-span-2">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Logo Assets (URL)</label>
                  <div className="flex gap-4 items-center">
                    <div className="w-16 h-16 rounded-2xl bg-gray-50 border border-gray-200 overflow-hidden flex-shrink-0">
