                      formErrors.rtp ? 'border-rose-300 focus:ring-rose-500/20 bg-rose-50/20' : 'border-gray-200 focus:ring-indigo-500/20'
                    }`}
                  />
                  {formErrors.rtp && (
                    <p className="text-[10px] font-bold text-rose-500 ml-1">{formErrors.rtp}</p>
                  )}
                </div>

                {/* Volatility */}
                <div className="space-y-1.5">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Volatility Level</label>
                  <select 
                    name="volatility"
                    value={editingGame?.volatility || ''}
                    onChange={handleGameInputChange}
