              </div>

              {/* How to Play Section */}
              <div className="space-y-1.5">
                <div className="flex items-center justify-between">
                  <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">How to Play (Concise Instructions)</label>
                  <span className="text-[9px] text-gray-400 font-bold uppercase">Max 4 Bullet Points</span>
                </div>
                <textarea 
                  name="howToPlay"
                  rows={4}
                  value={Array.isArray(editingGame?.howToPlay) ? editingGame.howToPlay.join('\n') : ''}
                  onChange={(e) => {
                    const lines = e.target.value.split('\n');
                    // We keep it as a newline string in the form but will map to array for save
                    // For the sake of this prototype, we update the array immediately
                    setEditingGame(prev => prev ? { ...prev, howToPlay: lines } : prev);
                    validateField('howToPlay', e.target.value);
                  }}
                  placeholder="e.g. Match 3 symbols to win&#10;Trigger free spins with 3 scatters"
                  className={`w-full bg-gray-50 border px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 transition-all font-medium ${
                    formErrors.howToPlay ? 'border-rose-300 focus:ring-rose-500/20 bg-rose-50/20' : 'border-gray-200 focus:ring-indigo-500/20'
                  }`}
                />
                {formErrors.howToPlay ? (
                  <p className="text-[10px] font-bold text-rose-500 ml-1">{formErrors.howToPlay}</p>
                ) : (
                  <p className="text-[9px] text-gray-400 ml-1">Each new line represents a bullet point. Keep it technical and brief.</p>
                )}
              </div>

              <div className="space-y-1.5">
                <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Simulation URL (Demo)</label>
                <input 
                  type="url" 
                  name="demoUrl"
                  value={editingGame?.demoUrl || ''}
                  onChange={handleGameInputChange}
                  placeholder="https://..."
                  className="w-full bg-gray-50 border border-gray-200 px-4 py-3 rounded-xl text-sm text-gray-900 outline-none focus:ring-2 focus:ring-indigo-500/20" 
                />
              </div>

              <div className="flex items-center gap-3 p-4 bg-indigo-50/50 rounded-2xl border border-indigo-100">
                <input 
                  type="checkbox" 
                  name="isPublished"
                  checked={editingGame?.isPublished || false}
                  onChange={handleGameInputChange}
                  id="publish_check"
                  className="w-4 h-4 text-indigo-600 border-gray-300 rounded focus:ring-indigo-500" 
                />
                <label htmlFor="publish_check" className="text-sm font-bold text-indigo-900 cursor-pointer">
                  Publicly visible on the platform
                </label>
              </div>
            </form>
            <footer className="p-8 border-t border-gray-100 flex justify-end gap-3 bg-gray-50/50">
              <button onClick={() => setIsModalOpen(false)} className="px-6 py-2.5 text-sm font-bold text-gray-500">Discard</button>
              <button 
                onClick={() => setIsModalOpen(false)}
                className="px-8 py-2.5 bg-indigo-600 text-white text-sm font-bold rounded-xl shadow-lg shadow-indigo-100"
              >
                Save Model
              </button>
            </footer>
          </div>
        </div>
      )}
    </div>
  );
};

