import React, { useState, useMemo } from 'react';
import { SlotGame, Volatility } from '../types';

interface RTPRankingsProps {
  games: SlotGame[];
  onSelectGame: (game: SlotGame) => void;
}

const RTPRankings: React.FC<RTPRankingsProps> = ({ games, onSelectGame }) => {
  const [filterRtp, setFilterRtp] = useState('All');
  const [filterVolatility, setFilterVolatility] = useState('All');
  const [sortBy, setSortBy] = useState<'highest' | 'lowest' | 'alpha'>('highest');

  const filteredAndSortedGames = useMemo(() => {
    let result = [...games];

    if (filterRtp !== 'All') {
      result = result.filter(g => {
        if (filterRtp === 'below-94') return g.rtp < 94;
        if (filterRtp === '94-96') return g.rtp >= 94 && g.rtp < 96;
        if (filterRtp === 'above-96') return g.rtp >= 96;
        return true;
      });
    }

    if (filterVolatility !== 'All') {
      result = result.filter(g => g.volatility === filterVolatility);
    }

    result.sort((a, b) => {
      if (sortBy === 'highest') return b.rtp - a.rtp;
      if (sortBy === 'lowest') return a.rtp - b.rtp;
      return a.title.localeCompare(b.title);
    });

    return result;
  }, [games, filterRtp, filterVolatility, sortBy]);

  const getRtpTierColor = (rtp: number) => {
    if (rtp >= 97) return 'emerald';
    if (rtp >= 96) return 'indigo';
    if (rtp >= 94) return 'slate';
    return 'gray';
  };

  const getVolatilityChipStyle = (v: string, active: boolean) => {
    if (!active) return 'bg-white text-gray-400 border-gray-100 hover:border-gray-300';
    switch (v) {
      case Volatility.LOW: return 'bg-emerald-50 text-emerald-700 border-emerald-200 shadow-sm shadow-emerald-100';
      case Volatility.MEDIUM: return 'bg-blue-50 text-blue-700 border-blue-200 shadow-sm shadow-blue-100';
      case Volatility.HIGH: return 'bg-amber-50 text-amber-700 border-amber-200 shadow-sm shadow-amber-100';
      case Volatility.EXTREME: return 'bg-rose-50 text-rose-700 border-rose-200 shadow-sm shadow-rose-100';
      default: return 'bg-indigo-50 text-indigo-700 border-indigo-200';
    }
  };

  return (
    <div className="bg-white min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12 space-y-12">
        {/* Page Header */}
        <header className="space-y-4">
          <div className="flex items-center gap-2 mb-2">
            <span className="w-8 h-px bg-indigo-600"></span>
            <span className="text-[10px] font-bold text-indigo-600 uppercase tracking-[0.2em]">Efficiency Index</span>
          </div>
          <h1 className="text-4xl sm:text-5xl font-extrabold text-gray-900 tracking-tight leading-none">
            RTP Performance Rankings
          </h1>
          <p className="text-lg text-gray-500 max-w-2xl leading-relaxed font-medium">
            Objective analysis of theoretical returns. Models are indexed by their mathematical efficiency benchmarks, calculated over millions of session iterations.
          </p>
        </header>

        {/* Global Efficiency Scale Visualizer */}
        <section className="bg-white border border-gray-100 p-8 rounded-[2.5rem] shadow-sm space-y-8 overflow-hidden">
          <div className="space-y-6">
            <div className="flex justify-between text-[9px] font-bold text-gray-400 uppercase tracking-widest px-1">
              <span>90.0% Baseline</span>
              <span>94.0%</span>
              <span>96.0% Mean</span>
              <span>98.0% Peak</span>
              <span>100% (Theo)</span>
            </div>

            <div className="relative h-6 w-full bg-gray-50 rounded-full border border-gray-100 shadow-inner flex overflow-hidden">
              {/* Scale Tiers with Neutral Gradients */}
              <div className="h-full w-[40%] bg-gradient-to-r from-slate-50 to-slate-200 border-r border-white/20" title="90-94%: Sub-Standard Efficiency" />
              <div className="h-full w-[20%] bg-gradient-to-r from-slate-200 to-indigo-200 border-r border-white/20" title="94-96%: Market Average Efficiency" />
              <div className="h-full w-[40%] bg-gradient-to-r from-indigo-200 to-emerald-200" title="96%+: High Performance Efficiency" />

              {/* Tick Markers */}
              <div className="absolute inset-y-0 left-[40%] w-px bg-white/40" />
              <div className="absolute inset-y-0 left-[60%] w-px bg-white/40" />
              <div className="absolute inset-y-0 left-[80%] w-px bg-white/40" />

              {/* Glass overlay */}
              <div className="absolute inset-0 bg-gradient-to-b from-white/10 to-transparent pointer-events-none" />
            </div>

            <div className="grid grid-cols-1 md:grid-cols-3 gap-8 pt-2">
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-slate-300" />
                   <h4 className="text-xs font-bold text-gray-900 uppercase tracking-tight">Sub-Standard Tier</h4>
                </div>
                <p className="text-[10px] text-gray-500 leading-relaxed">
                  Models returning below 94%. These typically feature aggressive house edges often found in legacy physical environments or extremely high-variance boutique models.
                </p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-indigo-400" />
                   <h4 className="text-xs font-bold text-gray-900 uppercase tracking-tight">Market Median Tier</h4>
                </div>
                <p className="text-[10px] text-gray-500 leading-relaxed">
                  The current industry standard range (94% - 96%). Designed for a balanced mathematical equilibrium between developer profitability and player session longevity.
                </p>
              </div>
              <div className="space-y-2">
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-emerald-400" />
                   <h4 className="text-xs font-bold text-gray-900 uppercase tracking-tight">Peak Performance Tier</h4>
                </div>
                <p className="text-[10px] text-gray-500 leading-relaxed">
                  Elite mathematical models exceeding 96%. These represent the top percentile of technical efficiency, prioritized for transparency and professional play profiles.
                </p>
              </div>
            </div>
          </div>
        </section>

        {/* Filters Section */}
        <section className="bg-white border border-gray-100 p-8 rounded-[2.5rem] shadow-sm space-y-8">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">
            {/* RTP Range Segments */}
            <div className="lg:col-span-5 space-y-4">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Efficiency Threshold</label>
              <div className="flex bg-gray-50 p-1 rounded-2xl border border-gray-100">
                {[
                  { id: 'All', label: 'All Models' },
                  { id: 'below-94', label: '< 94% (Sub)' },
                  { id: '94-96', label: '94-96% (Median)' },
                  { id: 'above-96', label: '96%+ (Peak)' },
                ].map((range) => (
                  <button
                    key={range.id}
                    onClick={() => setFilterRtp(range.id)}
                    className={`flex-1 py-2.5 px-2 text-[11px] font-bold rounded-xl transition-all ${
                      filterRtp === range.id 
                      ? 'bg-white text-indigo-600 shadow-sm border border-indigo-50' 
                      : 'text-gray-400 hover:text-gray-600'
                    }`}
                  >
                    {range.label}
                  </button>
                ))}
              </div>
            </div>

            {/* Volatility Chips */}
            <div className="lg:col-span-4 space-y-4">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Variance Profile</label>
              <div className="flex flex-wrap gap-2">
                <button
                  onClick={() => setFilterVolatility('All')}
                  className={`px-4 py-2.5 text-[11px] font-bold rounded-xl border transition-all ${
                    filterVolatility === 'All' 
                    ? 'bg-gray-900 text-white border-gray-900' 
                    : 'bg-white text-gray-400 border-gray-100 hover:border-gray-300'
                  }`}
                >
                  All
                </button>
                {Object.values(Volatility).map((v) => (
                  <button
                    key={v}
                    onClick={() => setFilterVolatility(v)}
                    className={`px-4 py-2.5 text-[11px] font-bold rounded-xl border transition-all ${getVolatilityChipStyle(v, filterVolatility === v)}`}
                  >
                    {v}
                  </button>
                ))}
              </div>
            </div>

            {/* Sort Control */}
            <div className="lg:col-span-3 space-y-4">
              <label className="text-[10px] font-bold text-gray-400 uppercase tracking-widest ml-1">Rank By</label>
              <div className="relative group">
                <select 
                  value={sortBy}
                  onChange={(e) => setSortBy(e.target.value as any)}
                  className="w-full bg-gray-50 border border-gray-100 rounded-2xl px-4 py-2.5 text-[11px] font-bold text-gray-700 outline-none focus:ring-4 focus:ring-indigo-500/5 transition-all appearance-none cursor-pointer"
                >
                  <option value="highest">Theoretical RTP (High → Low)</option>
                  <option value="lowest">Theoretical RTP (Low → High)</option>
                  <option value="alpha">Alphabetical (A-Z)</option>
                </select>
                <div className="absolute inset-y-0 right-4 flex items-center pointer-events-none text-gray-400">
                  <svg className="w-4 h-4" fill="none" stroke="currentColor" viewBox="0 0 24 24">
                    <path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2} d="M19 9l-7 7-7-7" />
                  </svg>
                </div>
              </div>
            </div>
          </div>
        </section>

        {/* Main List */}
        <section className="space-y-4">
          <div className="flex items-center justify-between px-6 py-2">
