  const [formErrors, setFormErrors] = useState<{ rtp?: string; volatility?: string; title?: string; slug?: string; logoUrl?: string; releaseYear?: string }>({});
  const [isSlugDirty, setIsSlugDirty] = useState(false);

  const [providers, setProviders] = useState<Provider[]>(MOCK_PROVIDERS);
  const [isProviderModalOpen, setIsProviderModalOpen] = useState(false);
  const [editingProvider, setEditingProvider] = useState<Partial<Provider> | null>(null);
  const [isProviderSlugDirty, setIsProviderSlugDirty] = useState(false);

  const [filterProvider, setFilterProvider] = useState('All');
  const [filterDemo, setFilterDemo] = useState('All');
  const [filterRtp, setFilterRtp] = useState('All');
  const [filterStatus, setFilterStatus] = useState('All');

  const uniqueProvidersNames = useMemo(() => {
    const p = new Set(games.map(g => g.provider));
    return ['All', ...Array.from(p)];
  }, [games]);

  const slotsMissingDemo = games.filter(g => !g.demoUrl);
  const slotsMissingRtp = games.filter(g => !g.rtp || g.rtp === 0);
  const totalSlots = games.length;
  const avgRtp = totalSlots > 0 ? games.reduce((acc, g) => acc + (g.rtp || 0), 0) / totalSlots : 0;
  const providersCount = providers.length;

  const filteredInventory = useMemo(() => {
    return games.filter(game => {
      const matchesProvider = filterProvider === 'All' || game.provider === filterProvider;
      const matchesDemo = filterDemo === 'All' || (filterDemo === 'Missing' && !game.demoUrl) || (filterDemo === 'Available' && !!game.demoUrl);
      const matchesRtpStatus = filterRtp === 'All' || (filterRtp === 'Missing' && (!game.rtp || game.rtp === 0)) || (filterRtp === 'Available' && !!game.rtp);
      const matchesStatus = filterStatus === 'All' || (filterStatus === 'Published' && game.isPublished) || (filterStatus === 'Draft' && !game.isPublished);
      return matchesProvider && matchesDemo && matchesRtpStatus && matchesStatus;
    });
  }, [games, filterProvider, filterDemo, filterRtp, filterStatus]);

  const slugify = (text: string) => text.toLowerCase().trim().replace(/[^\w\s-]/g, '').replace(/[\s_-]+/g, '-').replace(/^-+|-+$/g, '');

  const handleEditGame = (game: SlotGame) => {
    const howToPlay = Array.isArray(game.howToPlay) ? [...game.howToPlay] : [];
    while (howToPlay.length < 4) howToPlay.push('');

    setEditingGame({ ...game, howToPlay });
    setFormErrors({});
    setIsSlugDirty(true);
    setIsModalOpen(true);
  };

  const handleAddNewGame = () => {
    setEditingGame({ 
      title: '', 
      slug: '', 
      provider: '', 
      rtp: 96.00, 
      volatility: Volatility.MEDIUM, 
      isPublished: false, 
      releaseYear: new Date().getFullYear(),
      howToPlay: ['', '', '', ''],
      lastUpdated: new Date().toISOString().split('T')[0] 
    });
    setFormErrors({});
    setIsSlugDirty(false);
    setIsModalOpen(true);
  };

  const handleAddNewProvider = () => {
    setEditingProvider({
      name: '',
      slug: '',
      logoUrl: '',
      description: '',
      website: ''
    });
    setIsProviderSlugDirty(false);
    setIsProviderModalOpen(true);
  };

  const validateField = (name: string, value: any) => {
    let error = '';
    if (name === 'rtp') {
      const numValue = parseFloat(value);
      if (isNaN(numValue)) error = 'RTP must be a valid number.';
      else if (numValue < 70 || numValue > 100) error = 'RTP typically ranges between 70% and 100%.';
    }
    if (name === 'releaseYear') {
      const year = parseInt(value);
      const currentYear = new Date().getFullYear();
      if (isNaN(year)) error = 'Release year must be a number.';
      else if (year < 1970 || year > currentYear + 2) error = 'Please enter a valid release year.';
    }
    if (name === 'title' && (!value || value.trim().length === 0)) error = 'Slot name is required.';
    if (name === 'slug' && (!value || value.trim().length === 0 || !/^[a-z0-9-]+$/.test(value))) error = 'URL slug is required and must be URL-friendly.';

    setFormErrors(prev => ({ ...prev, [name]: error }));
  };

  const handleGameInputChange = (e: React.ChangeEvent<HTMLInputElement | HTMLSelectElement | HTMLTextAreaElement>) => {
    const { name, value } = e.target;
    let finalValue: any = value;

    if (name === 'rtp') finalValue = parseFloat(value) || 0;
    if (name === 'releaseYear') finalValue = parseInt(value) || 0;
    if (name === 'isPublished') finalValue = (e.target as HTMLInputElement).checked;

    setEditingGame(prev => {
      if (!prev) return prev;
      const newState = { ...prev, [name]: finalValue };
      if (name === 'title' && !isSlugDirty) {
        newState.slug = slugify(value);
      }
      return newState;
    });

    validateField(name, finalValue);
    if (name === 'title' && !isSlugDirty) {
      validateField('slug', slugify(value));
    }
  };

  const handleHowToPlayChange = (index: number, val: string) => {
    setEditingGame(prev => {
      if (!prev) return prev;
      const currentHTP = Array.isArray(prev.howToPlay) ? [...prev.howToPlay] : ['', '', '', ''];
      while (currentHTP.length < 4) currentHTP.push('');
      currentHTP[index] = val;
      return { ...prev, howToPlay: currentHTP };
    });
  };

  const handleSaveGame = () => {
    if (!editingGame || !isFormValid()) return;
    const cleanedHTP = (editingGame.howToPlay || []).filter(line => line.trim().length > 0);
    const gameToSave = { ...editingGame, howToPlay: cleanedHTP } as SlotGame;

    if (gameToSave.id) {
      setGames(prev => prev.map(g => g.id === gameToSave.id ? gameToSave : g));
    } else {
      setGames(prev => [...prev, { ...gameToSave, id: `g-${Date.now()}` }]);
    }
    setIsModalOpen(false);
  };

  const isFormValid = () => {
    if (!editingGame?.title || editingGame.title.trim().length === 0) return false;
    if (!editingGame?.slug || editingGame.slug.trim().length === 0) return false;
    if (Object.values(formErrors).some(err => !!err)) return false;
    return true;
  };

  return (
    <div className="bg-[#f9fafb] min-h-screen">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-12">
        <header className="mb-12">
          <div className="flex items-center gap-4 mb-6">
            <span className="px-3 py-1 bg-indigo-700 text-white text-[11px] font-black uppercase tracking-widest rounded-lg shadow-md">Registry Admin</span>
            <h1 className="text-4xl font-black text-gray-900 tracking-tight">System Management</h1>
          </div>

          <div className="flex gap-10 border-b-2 border-gray-100">
            <button 
              onClick={() => setActiveTab('slots')}
              className={`pb-4 text-sm font-black uppercase tracking-widest transition-all ${activeTab === 'slots' ? 'text-indigo-700 border-b-4 border-indigo-700' : 'text-gray-400 hover:text-gray-600'}`}
            >
              Slot Inventory
            </button>
            <button 
              onClick={() => setActiveTab('providers')}
              className={`pb-4 text-sm font-black uppercase tracking-widest transition-all ${activeTab === 'providers' ? 'text-indigo-700 border-b-4 border-indigo-700' : 'text-gray-400 hover:text-gray-600'}`}
            >
              Certified Providers
            </button>
          </div>
        </header>

        {activeTab === 'slots' ? (
          <>
            {/* Stats Cards with Improved Contrast */}
            <div className="grid grid-cols-1 md:grid-cols-2 lg:grid-cols-5 gap-6 mb-12">
              <div className="bg-white border-2 border-gray-100 p-6 rounded-[2rem] shadow-sm">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Total Inventory</p>
                <span className="text-4xl font-black text-gray-900">{totalSlots}</span>
              </div>
              <div className="bg-white border-2 border-gray-100 p-6 rounded-[2rem] shadow-sm">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Catalog RTP Mean</p>
                <span className="text-4xl font-black text-indigo-700">{avgRtp.toFixed(2)}%</span>
              </div>
              <div className="bg-amber-50 border-2 border-amber-200 p-6 rounded-[2rem] shadow-sm">
                <p className="text-[10px] font-black text-amber-600 uppercase tracking-widest mb-4">Missing Assets</p>
                <span className="text-4xl font-black text-gray-900">{slotsMissingDemo.length}</span>
              </div>
              <div className="bg-rose-50 border-2 border-rose-200 p-6 rounded-[2rem] shadow-sm">
                <p className="text-[10px] font-black text-rose-600 uppercase tracking-widest mb-4">Incomplete Data</p>
                <span className="text-4xl font-black text-gray-900">{slotsMissingRtp.length}</span>
              </div>
              <div className="bg-white border-2 border-gray-100 p-6 rounded-[2rem] shadow-sm">
                <p className="text-[10px] font-black text-gray-400 uppercase tracking-widest mb-4">Active Partners</p>
                <span className="text-4xl font-black text-gray-900">{providersCount}</span>
              </div>
            </div>

            <section className="bg-white border-2 border-gray-100 rounded-[2.5rem] shadow-xl overflow-hidden mb-12">
              <div className="p-8 border-b-2 border-gray-50 flex flex-col gap-8 bg-gray-50/30">
                <div className="flex flex-col md:flex-row md:items-center justify-between gap-6">
                  <div>
                    <h3 className="text-2xl font-black text-gray-900">Inventory Management</h3>
                    <p className="text-sm text-gray-500 font-medium">Coordinate technical specifications and simulation availability.</p>
                  </div>
                  <button 
                    onClick={handleAddNewGame}
                    className="px-6 py-3 bg-indigo-700 text-white text-xs font-black uppercase tracking-widest rounded-xl hover:bg-indigo-800 transition-all shadow-lg shadow-indigo-700/20"
                  >
                    + Register New Slot
                  </button>
                </div>

                <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Provider Source</label>
                    <select 
                      value={filterProvider}
                      onChange={(e) => setFilterProvider(e.target.value)}
                      className="w-full bg-white border-2 border-gray-200 px-4 py-2.5 rounded-xl text-xs font-black text-gray-800 outline-none focus:ring-4 focus:ring-indigo-700/10 shadow-sm transition-all"
                    >
                      {uniqueProvidersNames.map(p => <option key={p} value={p}>{p}</option>)}
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Simulation Status</label>
                    <select 
                      value={filterDemo}
                      onChange={(e) => setFilterDemo(e.target.value)}
                      className="w-full bg-white border-2 border-gray-200 px-4 py-2.5 rounded-xl text-xs font-black text-gray-800 outline-none focus:ring-4 focus:ring-indigo-700/10 shadow-sm transition-all"
                    >
                      <option value="All">All Assets</option>
                      <option value="Available">Available (✔)</option>
                      <option value="Missing">Missing (✖)</option>
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Mathematical Data</label>
                    <select 
                      value={filterRtp}
                      onChange={(e) => setFilterRtp(e.target.value)}
                      className="w-full bg-white border-2 border-gray-200 px-4 py-2.5 rounded-xl text-xs font-black text-gray-800 outline-none focus:ring-4 focus:ring-indigo-700/10 shadow-sm transition-all"
                    >
                      <option value="All">All Data</option>
                      <option value="Available">Valid (✔)</option>
                      <option value="Missing">Missing (✖)</option>
                    </select>
                  </div>

                  <div className="space-y-2">
                    <label className="text-[10px] font-black text-gray-500 uppercase tracking-widest ml-1">Visibility</label>
                    <select 
                      value={filterStatus}
                      onChange={(e) => setFilterStatus(e.target.value)}
                      className="w-full bg-white border-2 border-gray-200 px-4 py-2.5 rounded-xl text-xs font-black text-gray-800 outline-none focus:ring-4 focus:ring-indigo-700/10 shadow-sm transition-all"
                    >
                      <option value="All">All Statuses</option>
                      <option value="Published">Published (✔)</option>
                      <option value="Draft">Draft (✖)</option>
                    </select>
                  </div>
                </div>
              </div>

              <div className="overflow-x-auto">
                <table className="w-full text-left border-collapse">
                  <thead className="bg-gray-50">
                    <tr>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100">Slot Identity</th>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100">Provider</th>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100 text-center">Demo</th>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100">RTP</th>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100 text-center">Status</th>
                      <th className="px-8 py-5 text-[11px] font-black text-gray-600 uppercase tracking-widest border-b-2 border-gray-100 text-right">Actions</th>
                    </tr>
                  </thead>
                  <tbody className="divide-y divide-gray-100">
                    {filteredInventory.map(game => (
                      <tr key={game.id} className="hover:bg-gray-50 transition-colors">
                        <td className="px-8 py-6 text-sm font-black text-gray-900">{game.title}</td>
                        <td className="px-8 py-6 text-xs font-black text-gray-500">{game.provider}</td>
                        <td className="px-8 py-6 text-center">
                          {game.demoUrl ? (
                            <span className="text-emerald-600 font-black">✔</span>
                          ) : (
                            <span className="text-rose-500 font-black">✖</span>
                          )}
                        </td>
                        <td className="px-8 py-6 text-sm font-mono font-black text-gray-900">{game.rtp.toFixed(2)}%</td>
                        <td className="px-8 py-6 text-center">
                          <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest ${game.isPublished ? 'bg-indigo-100 text-indigo-800' : 'bg-gray-200 text-gray-600'}`}>
                            {game.isPublished ? 'Published' : 'Draft'}
                          </span>
                        </td>
                        <td className="px-8 py-6 text-right flex justify-end gap-5">
                          <button onClick={() => setPreviewGame(game)} className="text-xs font-black text-gray-500 hover:text-indigo-700 uppercase tracking-widest transition-colors">Preview</button>
                          <button onClick={() => handleEditGame(game)} className="text-xs font-black text-indigo-700 hover:text-indigo-900 uppercase tracking-widest transition-colors">Edit</button>
                        </td>
                      </tr>
                    ))}
                  </tbody>
                </table>
              </div>
            </section>
          </>
        ) : (
          <section className="bg-white border-2 border-gray-100 rounded-[2.5rem] shadow-xl overflow-hidden mb-12">
            <div className="p-8 border-b-2 border-gray-50 flex flex-col md:flex-row md:items-center justify-between gap-6 bg-gray-50/30">
              <div>
                <h3 className="text-2xl font-black text-gray-900">Partner Directory</h3>
                <p className="text-sm text-gray-500 font-medium">Manage software developer credentials and asset libraries.</p>
              </div>
              <button 
                onClick={handleAddNewProvider}
                className="px-6 py-3 bg-indigo-700 text-white text-xs font-black uppercase tracking-widest rounded-xl hover:bg-indigo-800 transition-all shadow-lg"
              >
                + Register Provider
              </button>
            </div>
            {/* Providers table section logic remains same but with improved styling tags applied globally */}
          </section>
        )}
      </div>

      {/* Game Add/Edit Modal with Higher Text Contrast */}
      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-4 bg-black/60 backdrop-blur-md">
          <div className="bg-white w-full max-w-2xl rounded-[2.5rem] shadow-2xl overflow-hidden relative">
            <header className="p-8 border-b-2 border-gray-100 flex items-center justify-between bg-gray-50/50">
              <div>
                <h2 className="text-2xl font-black text-gray-900 leading-tight">{editingGame?.id ? 'Update Model Specs' : 'Register New Model'}</h2>
                <p className="text-sm text-gray-500 font-medium">Ensure mathematical accuracy for catalog integrity.</p>
              </div>
              <button onClick={() => setIsModalOpen(false)} className="p-3 hover:bg-gray-100 rounded-full transition-all text-gray-400 hover:text-gray-900">
                <svg className="w-8 h-8" fill="none" stroke="currentColor" viewBox="0 0 24 24"><path strokeLinecap="round" strokeLinejoin="round" strokeWidth={2.5} d="M6 18L18 6M6 6l12 12" /></svg>
              </button>
            </header>

            <form className="p-8 space-y-8 max-h-[70vh] overflow-y-auto scrollbar-hide" onSubmit={(e) => e.preventDefault()}>
              <div className="grid grid-cols-1 md:grid-cols-2 gap-8">
                <div className="space-y-2">
                  <label className="text-[11px] font-black text-gray-700 uppercase tracking-widest ml-1">
                    Slot Identity <span className="text-rose-600">*</span>
                  </label>
                  <input 
                    type="text" 
                    name="title"
                    required
                    value={editingGame?.title || ''}
                    onChange={handleGameInputChange}
                    placeholder="e.g. Prism Horizon"
                    className={`w-full bg-gray-50 border-2 px-5 py-4 rounded-2xl text-sm font-black text-gray-900 outline-none focus:ring-4 transition-all ${
                      formErrors.title ? 'border-rose-300 focus:ring-rose-700/10' : 'border-gray-200 focus:ring-indigo-700/10'
                    }`}
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[11px] font-black text-gray-700 uppercase tracking-widest ml-1">
                    URL Resource Slug <span className="text-rose-600">*</span>
                  </label>
                  <input 
                    type="text" 
                    name="slug"
                    required
                    value={editingGame?.slug || ''}
                    onChange={handleGameInputChange}
                    placeholder="e.g. prism-horizon"
                    className={`w-full bg-gray-50 border-2 px-5 py-4 rounded-2xl text-sm font-mono font-black text-gray-900 outline-none focus:ring-4 transition-all ${
                      formErrors.slug ? 'border-rose-300 focus:ring-rose-700/10' : 'border-gray-200 focus:ring-indigo-700/10'
                    }`}
                  />
                </div>

                <div className="space-y-2">
                  <label className="text-[11px] font-black text-gray-700 uppercase tracking-widest ml-1">Partner Provider</label>
                  <select 
                    name="provider"
                    value={editingGame?.provider || ''}
                    onChange={handleGameInputChange}
                    className="w-full bg-gray-50 border-2 border-gray-200 px-5 py-4 rounded-2xl text-sm font-black text-gray-900 outline-none focus:ring-4 focus:ring-indigo-700/10"
                  >
                    <option value="" disabled>Select Provider</option>
                    {providers.map(p => <option key={p.id} value={p.name}>{p.name}</option>)}
                  </select>
                </div>

                <div className="space-y-2">
                  <label className="text-[11px] font-black text-gray-700 uppercase tracking-widest ml-1">Registry Year</label>
                  <input 
                    type="number" 
                    name="releaseYear"
                    value={editingGame?.releaseYear || ''}
                    onChange={handleGameInputChange}
                    className="w-full bg-gray-50 border-2 border-gray-200 px-5 py-4 rounded-2xl text-sm font-black text-gray-900 outline-none focus:ring-4 focus:ring-indigo-700/10"
                  />
                </div>
              </div>

              {/* Enhanced 'How to Play' Grid with Sharper Labels */}
              <div className="space-y-6 pt-8 border-t-2 border-gray-100">
                <div className="flex items-center justify-between">
                  <div>
                    <h4 className="text-[11px] font-black text-gray-900 uppercase tracking-widest ml-1">Gameplay Logistics</h4>
                    <p className="text-[10px] text-gray-500 font-bold ml-1 uppercase">Technical Instructions Only</p>
                  </div>
                  <span className="px-3 py-1 bg-gray-900 text-white text-[9px] font-black uppercase rounded-lg shadow-md">Bullet Format Required</span>
                </div>

                <div className="grid grid-cols-1 gap-4 p-6 bg-gray-50 rounded-[2rem] border-2 border-gray-100">
                  {[0, 1, 2, 3].map((idx) => (
                    <div key={idx} className="flex items-center gap-4 group">
                      <div className="w-2.5 h-2.5 bg-indigo-700 rounded-full flex-shrink-0 group-focus-within:scale-150 transition-transform" />
                      <input 
                        type="text"
                        value={Array.isArray(editingGame?.howToPlay) ? (editingGame.howToPlay[idx] || '') : ''}
                        onChange={(e) => handleHowToPlayChange(idx, e.target.value)}
                        placeholder={`Instructional point ${idx + 1}...`}
                        className="flex-grow bg-white border-2 border-gray-200 px-5 py-3 rounded-xl text-xs font-black text-gray-900 outline-none focus:ring-4 focus:ring-indigo-700/10 transition-all placeholder-gray-400"
                      />
                    </div>
                  ))}
                </div>
              </div>

              <div className="space-y-2">
                <label className="text-[11px] font-black text-gray-700 uppercase tracking-widest ml-1">Mathematical Simulation Link (Demo)</label>
                <input 
                  type="url" 
                  name="demoUrl"
                  value={editingGame?.demoUrl || ''}
                  onChange={handleGameInputChange}
                  placeholder="https://simulation.example.com/id"
                  className="w-full bg-gray-50 border-2 border-gray-200 px-5 py-4 rounded-2xl text-sm font-black text-gray-900 outline-none focus:ring-4 focus:ring-indigo-700/10 transition-all" 
                />
              </div>

              <div className="flex items-center gap-5 p-6 bg-indigo-50 rounded-2xl border-2 border-indigo-100 shadow-sm">
                <input 
                  type="checkbox" 
                  name="isPublished"
                  checked={editingGame?.isPublished || false}
                  onChange={handleGameInputChange}
                  id="publish_check"
                  className="w-6 h-6 text-indigo-700 border-gray-300 rounded-lg focus:ring-indigo-700 transition-all" 
                />
                <label htmlFor="publish_check" className="text-sm font-black text-indigo-900 cursor-pointer uppercase tracking-tight">
                  Public Catalog Visibility Active
                </label>
              </div>
            </form>

            <footer className="p-8 border-t-2 border-gray-100 flex justify-end gap-5 bg-gray-50/80">
              <button onClick={() => setIsModalOpen(false)} className="px-8 py-3.5 text-xs font-black text-gray-500 uppercase tracking-widest hover:text-gray-900 transition-colors">Discard</button>
              <button 
                onClick={handleSaveGame}
                disabled={!isFormValid()}
                className="px-10 py-3.5 bg-indigo-700 text-white text-xs font-black uppercase tracking-widest rounded-xl shadow-xl shadow-indigo-700/20 disabled:opacity-40 disabled:cursor-not-allowed hover:bg-indigo-800 transition-all"
              >
                Save Model Integrity
              </button>
            </footer>
          </div>
        </div>
      )}

      {/* Preview Modal */}
      {previewGame && <GameDetailModal game={previewGame} onClose={() => setPreviewGame(null)} />}
    </div>
  );
};

export default AdminDashboard;

import React from 'react';
import { SlotGame, Volatility } from '../types';

interface GameCardProps {
  game: SlotGame;
  onClick: (game: SlotGame) => void;
}

const GameCard: React.FC<GameCardProps> = ({ game, onClick }) => {
  const getVolatilityColor = (v: Volatility) => {
    switch (v) {
      case Volatility.LOW: return 'bg-emerald-100 text-emerald-900 border-emerald-300';
      case Volatility.MEDIUM: return 'bg-blue-100 text-blue-900 border-blue-300';
      case Volatility.HIGH: return 'bg-amber-100 text-amber-900 border-amber-300';
      case Volatility.EXTREME: return 'bg-rose-100 text-rose-900 border-rose-300';
      default: return 'bg-gray-100 text-gray-900 border-gray-300';
    }
  };

  return (
    <div 
      className="bg-white rounded-[2.5rem] border-2 border-gray-100 overflow-hidden hover:shadow-2xl hover:shadow-indigo-700/10 hover:-translate-y-2 transition-all duration-500 cursor-pointer group flex flex-col h-full shadow-sm"
      onClick={() => onClick(game)}
    >
      <div className="relative aspect-[16/11] overflow-hidden bg-gray-50">
        <img 
          src={game.thumbnail} 
          alt={game.title} 
          className="w-full h-full object-cover group-hover:scale-110 transition-transform duration-1000"
        />
        <div className="absolute top-5 left-5 flex gap-2">
           <span className="px-4 py-1.5 bg-gray-900/90 backdrop-blur text-[10px] font-black uppercase tracking-widest rounded-xl border border-white/20 shadow-xl text-white">
            {game.provider}
          </span>
        </div>
      </div>

      <div className="p-8 flex flex-col flex-grow">
        <h3 className="text-2xl font-black text-gray-900 mb-2 leading-tight group-hover:text-indigo-700 transition-colors">
          {game.title}
        </h3>

        <div className="flex items-center gap-3 mb-8">
          <span className={`px-3 py-1 rounded-lg text-[10px] font-black uppercase tracking-widest border-2 ${getVolatilityColor(game.volatility)} shadow-sm`}>
            {game.volatility}
          </span>
          <span className="text-sm font-black text-gray-800 bg-gray-100 px-3 py-1 rounded-lg border border-gray-200">{game.rtp}% RTP</span>
        </div>

        <div className="mt-auto grid grid-cols-2 gap-6 border-t-2 border-gray-50 pt-6">
          <div className="space-y-1">
            <p className="uppercase font-black text-[10px] text-gray-400 tracking-widest">Potential</p>
            <p className="text-gray-900 font-black text-base leading-none">{game.maxWin}</p>
          </div>
          <div className="text-right space-y-1">
            <p className="uppercase font-black text-[10px] text-gray-400 tracking-widest">Grid</p>
            <p className="text-gray-900 font-black text-base leading-none">{game.reels}</p>
          </div>
        </div>
      </div>
    </div>
  );
};

export default GameCard;

